const recipes=[
{id:'oats',name:'Berry Overnight Oats',slot:'Breakfast',emoji:'🫐',cal:360,p:19,c:48,f:11,serv:1,ingredients:[['Rolled oats',0.5,'cup'],['Greek yogurt',0.5,'cup'],['Mixed berries',0.5,'cup'],['Milk',0.5,'cup']],steps:["Measure ½ cup rolled oats, ½ cup Greek yogurt and ½ cup milk into a sealable jar or bowl.","Stir thoroughly until all the oats are coated and no dry patches remain.","Cover and refrigerate at least 4 hours, preferably overnight, so the oats soften.","Just before eating, gently stir and top with ½ cup mixed berries. Serve chilled."]},
{id:'eggs',name:'Egg & Avocado Toast',slot:'Breakfast',emoji:'🥑',cal:420,p:22,c:31,f:23,serv:1,ingredients:[['Eggs',2,'each'],['Whole-grain bread',2,'slice'],['Avocado',0.5,'each']],steps:["Toast 2 slices whole-grain bread until golden.","Cut ½ avocado into thin slices or mash it with a fork and spread on the toast.","Crack the 2 eggs into a nonstick skillet over medium-low heat. Cook 2–3 minutes until the whites are opaque, flip gently, and continue until the yolks are cooked to your preference; for a fully cooked egg, the yolk should be firm.","Place one cooked egg on each slice of avocado toast and serve while warm."]},
{id:'smoothie',name:'Protein Banana Smoothie',slot:'Breakfast',emoji:'🍌',cal:320,p:30,c:40,f:5,serv:1,ingredients:[['Banana',1,'each'],['Milk',1,'cup'],['Protein powder',1,'scoop'],['Peanut butter',1,'tsp']],steps:["Peel 1 banana and break it into chunks.","Add banana, 1 cup milk, 1 scoop protein powder and 1 tsp peanut butter to a blender.","Blend for about 30–45 seconds until the powder dissolves and the smoothie is completely smooth.","Pour into a glass and serve immediately. If too thick, add a little water and blend again."]},
{id:'chicken',name:'Chicken Rice Bowl',slot:'Lunch',emoji:'🍗',cal:540,p:46,c:57,f:13,serv:1,ingredients:[['Chicken breast',6,'oz'],['Brown rice',1,'cup'],['Broccoli',1,'cup'],['Olive oil',1,'tsp']],steps:["For 1 serving, measure 1 cup COOKED brown rice (roughly ⅓ cup dry rice; check the package yield). If starting with dry rice, rinse it, add the package-specified water, cover, and simmer until tender, usually 35–45 minutes. Measure 1 cup after cooking.","Cut 6 oz chicken breast into bite-sized pieces. Heat a nonstick skillet over medium heat and cook 6–9 minutes, stirring, until 165°F.","Steam 1 cup broccoli in a covered pan with 2 tbsp water for 4–5 minutes until fork-tender.","Toss the cooked broccoli with 1 tsp olive oil. Serve the chicken and broccoli on 1 cup hot cooked brown rice."]},
{id:'wrap',name:'Turkey Hummus Wrap',slot:'Lunch',emoji:'🌯',cal:460,p:35,c:44,f:17,serv:1,ingredients:[['Whole-wheat tortilla',1,'each'],['Turkey slices',4,'oz'],['Hummus',2,'tbsp'],['Spinach',1,'cup']],steps:["Lay out 1 whole-wheat tortilla and spread 2 tbsp hummus evenly across the center.","Layer 4 oz ready-to-eat turkey slices over hummus.","Wash, dry and add 1 cup spinach over the turkey.","Fold the left and right sides inward, then roll tightly from the bottom. Slice in half to serve."]},
{id:'salad',name:'Chickpea Power Salad',slot:'Lunch',emoji:'🥗',cal:480,p:19,c:53,f:23,serv:1,ingredients:[['Chickpeas',1,'cup'],['Cucumber',0.5,'each'],['Cherry tomatoes',0.5,'cup'],['Feta',1,'oz'],['Olive oil',1,'tbsp']],steps:["Drain and rinse 1 cup cooked chickpeas and place in a bowl.","Dice ½ cucumber and halve ½ cup cherry tomatoes; add them to the chickpeas.","Crumble 1 oz feta cheese over the vegetables.","Drizzle 1 tbsp olive oil over everything and toss gently until evenly coated. Serve chilled or at room temperature."]},
{id:'salmon',name:'Salmon & Sweet Potato',slot:'Dinner',emoji:'🐟',cal:590,p:43,c:48,f:25,serv:1,ingredients:[['Salmon fillet',6,'oz'],['Sweet potato',1,'each'],['Green beans',1,'cup'],['Olive oil',1,'tsp']],steps:["Preheat oven to 400°F. Dice 1 sweet potato into even ½-inch cubes and place on a lined baking sheet.","Toss sweet potato with ½ tsp of the 1 tsp olive oil. Roast for 15 minutes.","Toss 1 cup green beans with the remaining ½ tsp olive oil and add to the baking sheet beside the potatoes.","Place 6 oz salmon fillet on the sheet. Return to the oven for 12–16 minutes, until salmon reaches 145°F and the vegetables are tender.","Rest salmon for 2 minutes and serve with roasted potato and beans."]},
{id:'pasta',name:'Lean Turkey Pasta',slot:'Dinner',emoji:'🍝',cal:610,p:45,c:65,f:18,serv:1,ingredients:[['Lean ground turkey',5,'oz'],['Whole-wheat pasta',2,'oz'],['Tomato sauce',0.75,'cup'],['Spinach',1,'cup']],steps:["Cook 2 oz dry whole-wheat pasta in boiling water according to package directions, usually 8–12 minutes; drain.","Brown 5 oz lean ground turkey in a nonstick skillet over medium heat for 6–9 minutes, breaking into crumbles until it reaches 165°F.","Pour ¾ cup tomato sauce into the turkey and simmer 3–4 minutes.","Stir in 1 cup spinach and cook 1–2 minutes until wilted.","Add drained pasta and toss until evenly coated and steaming hot."]},
{id:'tofu',name:'Classic Stir-Fry',slot:'Dinner',emoji:'🥡',cal:520,p:44,c:54,f:13,serv:1,ingredients:[['Chicken breast',6,'oz'],['Mixed vegetables',2,'cup'],['Brown rice',0.75,'cup'],['Soy sauce',1,'tbsp']],steps:["Use ¾ cup COOKED brown rice for serving. If starting dry, measure roughly ¼ cup uncooked rice, follow its package water ratio, and simmer until tender (often 35–45 minutes); otherwise reheat ¾ cup cooked rice until steaming.","Cut 6 oz chicken breast into small even strips and measure 2 cups mixed vegetables.","Cook chicken in a nonstick skillet over medium-high heat for 6–9 minutes, turning until its center reaches 165°F.","Add 2 cups mixed vegetables with 2 tbsp water. Stir-fry 4–6 minutes until tender-crisp.","Add 1 tbsp soy sauce and toss for 1 minute. Serve everything over the brown rice."]},
{id:'yogurt',name:'Greek Yogurt & Fruit',slot:'Snack',emoji:'🍓',cal:210,p:19,c:27,f:3,serv:1,ingredients:[['Greek yogurt',1,'cup'],['Mixed berries',0.5,'cup']],steps:["Measure 1 cup Greek yogurt into a bowl.","Rinse and drain ½ cup mixed berries; slice any large strawberries.","Scatter all ½ cup berries over yogurt and serve chilled."]},
{id:'apple',name:'Apple & Peanut Butter',slot:'Snack',emoji:'🍎',cal:260,p:7,c:31,f:15,serv:1,ingredients:[['Apple',1,'each'],['Peanut butter',2,'tbsp']],steps:["Rinse and core 1 apple, then cut into thin wedges.","Measure 2 tbsp peanut butter into a small bowl.","Serve apple wedges alongside peanut butter for dipping."]},
{id:'nuts',name:'Trail Mix',slot:'Snack',emoji:'🥜',cal:200,p:6,c:16,f:14,serv:1,ingredients:[['Mixed nuts',0.25,'cup'],['Raisins',1,'tbsp']],steps:["Measure ¼ cup mixed nuts into a small bowl.","Measure 1 tbsp raisins and scatter them over the measured ¼ cup mixed nuts in the bowl.","Stir to combine and divide into a snack container or eat immediately."]}
];recipes.push(...[{"id":"pancakes","name":"Fluffy Pancakes","slot":"Breakfast","emoji":"🥞","cal":390,"p":12,"c":61,"f":11,"serv":1,"ingredients":[["Pancake mix",0.75,"cup"],["Milk",0.5,"cup"],["Eggs",1,"each"],["Maple syrup",2,"tbsp"]],"steps":["Whisk ¾ cup pancake mix, ½ cup milk and 1 egg in a bowl until just combined. A few lumps are fine.","Set a nonstick skillet over medium-low heat and warm it for about 2 minutes, until a drop of water gently sizzles on contact.","Pour batter into small ¼-cup rounds. Cook about 2–3 minutes until bubbles appear and the edges look set.","Flip each pancake and cook 1–2 minutes until golden and cooked through. Serve with 2 tbsp maple syrup."],"cuisine":"Breakfast"},{"id":"omelet","name":"Cheese & Spinach Omelet","slot":"Breakfast","emoji":"🍳","cal":340,"p":27,"c":6,"f":23,"serv":1,"ingredients":[["Eggs",3,"each"],["Spinach",1,"cup"],["Cheddar cheese",1,"oz"],["Butter",1,"tsp"]],"steps":["Crack 3 eggs into a bowl and beat until combined. Rinse and roughly chop 1 cup spinach; shred 1 oz cheddar.","Melt 1 tsp butter in an 8-inch nonstick skillet over medium-low heat. Add spinach and stir 1 minute until wilted.","Pour in the eggs, tilt to spread, and cook 2–3 minutes. Gently push the cooked edges toward the center so liquid egg runs underneath.","Sprinkle 1 oz cheddar over half the omelet, fold it, and cook another 1–2 minutes until the eggs are set and the cheese melts."],"cuisine":"Breakfast"},{"id":"frenchtoast","name":"French Toast","slot":"Breakfast","emoji":"🍞","cal":380,"p":18,"c":48,"f":14,"serv":1,"ingredients":[["Whole-grain bread",2,"slice"],["Eggs",2,"each"],["Milk",0.25,"cup"],["Cinnamon",0.25,"tsp"]],"steps":["Whisk 2 eggs, ¼ cup milk and ¼ tsp cinnamon together in a shallow dish until smooth.","Heat a nonstick pan over medium heat. Dip each of 2 slices whole-grain bread into the egg mixture for about 10 seconds on each side.","Place bread in the pan and cook 2–3 minutes on the first side until golden.","Flip and cook another 2–3 minutes until the coating is fully set, not wet in the center. Serve warm."],"cuisine":"Breakfast"},{"id":"burrito","name":"Breakfast Burrito","slot":"Breakfast","emoji":"🌯","cal":490,"p":29,"c":43,"f":23,"serv":1,"ingredients":[["Eggs",2,"each"],["Tortillas",1,"each"],["Potatoes",0.5,"cup"],["Cheddar cheese",1,"oz"]],"steps":["Dice ½ cup potatoes into small cubes. Simmer in water for 7–9 minutes until nearly tender; drain.","Cook the drained potatoes in a nonstick skillet over medium heat for 3–4 minutes until lightly golden.","Beat 2 eggs and pour them into the skillet. Stir gently for 2–3 minutes until eggs are fully set.","Warm 1 tortilla for 15–20 seconds, add the egg-potato mixture and 1 oz shredded cheddar, then fold in the sides and roll tightly."],"cuisine":"Breakfast"},{"id":"bagel","name":"Egg Breakfast Bagel","slot":"Breakfast","emoji":"🥯","cal":440,"p":25,"c":48,"f":17,"serv":1,"ingredients":[["Bagel",1,"each"],["Eggs",1,"each"],["Cheddar cheese",1,"oz"],["Turkey slices",2,"oz"]],"steps":["Split 1 bagel and toast until lightly golden. Set out 2 oz turkey slices and 1 oz cheddar.","Crack 1 egg into a nonstick skillet over medium-low heat; cook 2–3 minutes, flip and cook until the white and yolk reach your preferred fully cooked consistency.","Layer turkey and cheddar on one warm bagel half; place the cooked egg on top.","Cover with the other bagel half. Warm in the skillet 30–60 seconds if needed to melt the cheese."],"cuisine":"Breakfast"},{"id":"cereal","name":"Cereal & Banana","slot":"Breakfast","emoji":"🥣","cal":310,"p":12,"c":60,"f":4,"serv":1,"ingredients":[["Whole-grain cereal",1,"cup"],["Milk",1,"cup"],["Banana",1,"each"]],"steps":["Measure 1 cup whole-grain cereal into a bowl.","Peel 1 banana and cut it into thin slices.","Scatter the sliced banana over the cereal and pour in 1 cup milk. Serve immediately."],"cuisine":"Breakfast"},{"id":"tacos","name":"Chicken Street Tacos","slot":"Lunch","emoji":"🌮","cal":520,"p":38,"c":48,"f":19,"serv":1,"ingredients":[["Chicken breast",5,"oz"],["Corn tortillas",3,"each"],["Onion",0.25,"each"],["Cilantro",0.25,"cup"],["Lime",0.5,"each"]],"steps":["Slice 5 oz chicken breast into thin strips and dice ¼ onion. Chop ¼ cup cilantro and cut ½ lime into wedges.","Cook chicken strips in a nonstick skillet over medium heat for 6–9 minutes, turning until browned and 165°F in the center.","Heat 3 corn tortillas in a dry skillet for 15–30 seconds per side until warm and pliable.","Divide the cooked chicken across the tortillas, then top with diced onion, cilantro and a squeeze of lime."],"cuisine":"Mexican"},{"id":"quesadilla","name":"Black Bean Quesadillas","slot":"Lunch","emoji":"🫓","cal":480,"p":21,"c":58,"f":18,"serv":1,"ingredients":[["Flour tortillas",2,"each"],["Black beans",0.5,"cup"],["Cheddar cheese",1.5,"oz"],["Salsa",0.25,"cup"]],"steps":["Drain and rinse ½ cup black beans. Shred 1½ oz cheddar and measure ¼ cup salsa.","Set 1 flour tortilla in a dry skillet over medium-low heat. Spread beans and cheese evenly on the tortilla and cover with the second tortilla.","Cook for 2–3 minutes until the bottom is toasted and cheese starts to melt. Flip carefully using a broad spatula.","Cook the second side 2–3 minutes until golden and cheese is melted. Cut into wedges and serve with ¼ cup salsa."],"cuisine":"Mexican"},{"id":"friedrice","name":"Chicken Fried Rice","slot":"Lunch","emoji":"🍚","cal":530,"p":34,"c":62,"f":15,"serv":1,"ingredients":[["Cooked rice",1.25,"cup"],["Chicken breast",4,"oz"],["Eggs",1,"each"],["Mixed vegetables",1,"cup"],["Soy sauce",1,"tbsp"]],"steps":["Dice 4 oz chicken breast into small pieces. Beat 1 egg and measure 1 cup mixed vegetables and 1¼ cups cooked rice.","Cook chicken in a large nonstick skillet over medium-high heat for 5–7 minutes until 165°F; transfer to a plate.","Add mixed vegetables with 2 tbsp water and cook 3–4 minutes. Push to the side, pour in beaten egg and scramble until set.","Add the 1¼ cups cooked rice, cooked chicken and 1 tbsp soy sauce. Stir-fry 2–3 minutes until steaming hot throughout."],"cuisine":"Chinese"},{"id":"noodles","name":"Garlic Sesame Noodles","slot":"Lunch","emoji":"🍜","cal":480,"p":16,"c":66,"f":17,"serv":1,"ingredients":[["Noodles",3,"oz"],["Sesame oil",1,"tbsp"],["Soy sauce",1,"tbsp"],["Garlic",2,"clove"],["Scallions",2,"each"]],"steps":["Boil 3 oz dry noodles in water according to package directions, usually 5–9 minutes. Drain, reserving 2 tbsp cooking water.","Mince 2 cloves garlic and slice 2 scallions.","Heat 1 tbsp sesame oil in a skillet over medium-low heat. Cook the minced garlic for about 30 seconds, stirring so it does not burn.","Add noodles, 1 tbsp soy sauce and the reserved water. Toss 1–2 minutes until evenly coated; top with both sliced scallions."],"cuisine":"Chinese"},{"id":"soup","name":"Chicken Vegetable Soup","slot":"Lunch","emoji":"🍲","cal":360,"p":34,"c":34,"f":9,"serv":1,"ingredients":[["Chicken breast",5,"oz"],["Carrots",1,"each"],["Celery",1,"stalk"],["Chicken broth",2,"cup"],["Noodles",1,"oz"]],"steps":["Dice 5 oz chicken breast, slice 1 carrot and 1 celery stalk into small pieces.","Bring 2 cups chicken broth to a gentle boil in a saucepan. Add chicken, carrot and celery.","Reduce heat and simmer covered 10–12 minutes, until chicken reaches 165°F and the vegetables start to soften.","Stir in 1 oz dry noodles; simmer for the time on the noodle package, usually 5–8 minutes, until tender.","Check the chicken is cooked and the soup is steaming hot. Ladle into a bowl."],"cuisine":"American"},{"id":"sandwich","name":"Grilled Chicken Sandwich","slot":"Lunch","emoji":"🥪","cal":470,"p":42,"c":44,"f":13,"serv":1,"ingredients":[["Chicken breast",5,"oz"],["Burger bun",1,"each"],["Lettuce",1,"cup"],["Tomato",0.5,"each"],["Mayonnaise",1,"tbsp"]],"steps":["Slice ½ tomato and prepare 1 cup lettuce. Split 1 burger bun and set out 1 tbsp mayonnaise.","Flatten 5 oz chicken breast to an even thickness; cook in a nonstick skillet over medium heat for 5–7 minutes per side, depending on thickness, until 165°F.","Toast both halves of the burger bun cut-side down in the skillet for 30–60 seconds.","Spread 1 tbsp mayonnaise on the bun, add the cooked chicken, lettuce and tomato, and close the sandwich."],"cuisine":"American"},{"id":"fajitas","name":"Chicken Fajitas","slot":"Dinner","emoji":"🌶️","cal":590,"p":44,"c":49,"f":21,"serv":1,"ingredients":[["Chicken breast",6,"oz"],["Bell peppers",1,"each"],["Onion",0.5,"each"],["Tortillas",2,"each"],["Olive oil",1,"tbsp"]],"steps":["Slice 6 oz chicken breast, 1 bell pepper and ½ onion into thin strips.","Heat 1 tbsp olive oil in a skillet over medium-high heat. Add chicken and cook 5–7 minutes, turning, until 165°F; move chicken to a plate.","Cook sliced pepper and onion in the same skillet for 4–6 minutes until tender-crisp. Return chicken and toss 1 minute.","Warm 2 tortillas in a dry skillet for 20 seconds per side; divide the chicken and vegetables between them."],"cuisine":"Mexican"},{"id":"enchiladas","name":"Bean & Cheese Enchiladas","slot":"Dinner","emoji":"🫔","cal":620,"p":26,"c":72,"f":25,"serv":1,"ingredients":[["Corn tortillas",3,"each"],["Black beans",1,"cup"],["Enchilada sauce",0.75,"cup"],["Cheddar cheese",2,"oz"]],"steps":["Preheat oven to 375°F. Drain and rinse 1 cup black beans; shred 2 oz cheddar.","Spread 2 tbsp of the ¾ cup enchilada sauce across the bottom of a small baking dish.","Warm 3 corn tortillas briefly to soften. Divide the beans and half the cheddar among them; roll and place seam-side down in the dish.","Pour the remaining enchilada sauce over the rolled tortillas and sprinkle with remaining cheese.","Bake 15–20 minutes, until sauce bubbles and cheese is melted. Rest 3 minutes before serving."],"cuisine":"Mexican"},{"id":"stirfry","name":"Ginger Chicken Stir-Fry","slot":"Dinner","emoji":"🥡","cal":550,"p":45,"c":51,"f":17,"serv":1,"ingredients":[["Chicken breast",6,"oz"],["Broccoli",1,"cup"],["Bell peppers",1,"each"],["Cooked rice",1,"cup"],["Soy sauce",1,"tbsp"],["Ginger",1,"tsp"]],"steps":["Slice 6 oz chicken breast into thin strips. Cut 1 bell pepper into strips and chop 1 cup broccoli into small florets.","Heat a nonstick skillet over medium-high heat. Add the chicken and cook 5–7 minutes, turning until browned and the center reaches 165°F.","Add the 1 cup broccoli and sliced bell pepper with 2 tbsp water. Cover 3 minutes to soften, then uncover and cook 2 more minutes.","Stir in 1 tsp ginger and 1 tbsp soy sauce. Toss everything for 1 minute until coated.","Warm 1 cup already-cooked rice until steaming hot. Spoon the chicken and vegetables over the rice and serve."],"cuisine":"Chinese"},{"id":"beefbroccoli","name":"Beef & Broccoli","slot":"Dinner","emoji":"🥦","cal":570,"p":39,"c":50,"f":23,"serv":1,"ingredients":[["Beef strips",6,"oz"],["Broccoli",2,"cup"],["Cooked rice",1,"cup"],["Soy sauce",1,"tbsp"],["Garlic",2,"clove"]],"steps":["Thinly slice 6 oz beef strips against the grain if needed. Cut 2 cups broccoli into small florets and mince 2 cloves garlic.","Place a skillet over medium-high heat. Add the beef in a single layer and sear for about 2–3 minutes per side, until browned; transfer to a plate.","Add broccoli and 3 tbsp water to the same skillet. Cover and steam 3–4 minutes until crisp-tender; uncover.","Stir in the minced 2 garlic cloves and cook 30 seconds. Return beef to the pan, add 1 tbsp soy sauce and toss for 1–2 minutes until hot.","Heat 1 cup cooked rice until steaming. Serve the beef and broccoli over the rice."],"cuisine":"Chinese"},{"id":"spaghetti","name":"Spaghetti & Meatballs","slot":"Dinner","emoji":"🍝","cal":680,"p":39,"c":79,"f":23,"serv":1,"ingredients":[["Spaghetti",3,"oz"],["Ground beef",5,"oz"],["Tomato sauce",1,"cup"],["Parmesan",1,"tbsp"]],"steps":["Bring a pot of water to a rolling boil. Add 3 oz dry spaghetti and cook according to the package, usually 8–12 minutes, until tender; drain.","Divide 5 oz ground beef into 3 or 4 small meatballs, pressing each firmly together. Place in a nonstick skillet over medium heat.","Turn the meatballs every 2–3 minutes for about 10–12 minutes total, until browned and the centers reach 160°F.","Pour 1 cup tomato sauce into the skillet. Lower heat and simmer 5 minutes, stirring the sauce around the meatballs.","Put the spaghetti on a plate, spoon on the meatballs and sauce, and sprinkle with 1 tbsp Parmesan."],"cuisine":"Italian"},{"id":"chickenparm","name":"Chicken Parmesan","slot":"Dinner","emoji":"🧀","cal":650,"p":51,"c":59,"f":23,"serv":1,"ingredients":[["Chicken breast",6,"oz"],["Breadcrumbs",0.5,"cup"],["Mozzarella",1.5,"oz"],["Tomato sauce",0.5,"cup"],["Pasta",2,"oz"]],"steps":["Preheat the oven to 425°F. Bring a pot of water to a boil for 2 oz dry pasta.","Flatten 6 oz chicken breast to an even thickness of about ½ inch. Spread the measured ½ cup breadcrumbs on a plate and press the slightly damp chicken firmly into the crumbs on both sides. Set on the lined baking sheet; discard any crumbs that touched raw chicken.","Place the chicken on a parchment-lined baking sheet and bake 15–20 minutes, until the center reaches 165°F.","Meanwhile, boil 2 oz pasta according to the package, usually 8–12 minutes, and drain.","Spoon ½ cup tomato sauce over the cooked chicken and top with 1½ oz mozzarella. Return to the oven for 3–5 minutes until melted; serve with the pasta."],"cuisine":"Italian"}]);recipes.push(...[{"id":"waffles","name":"Classic Waffles","slot":"Breakfast","emoji":"🧇","cal":410,"p":12,"c":59,"f":14,"ingredients":[["Waffle mix",0.75,"cup"],["Milk",0.5,"cup"],["Eggs",1,"each"],["Maple syrup",2,"tbsp"]],"steps":["Preheat your waffle iron following its instructions. Whisk ¾ cup waffle mix, ½ cup milk and 1 egg until combined.","Lightly coat the iron only if the manufacturer recommends it. Pour in enough batter to cover the cooking grid without overflowing.","Close and cook about 3–5 minutes, or until the steam slows and the waffle is golden; cooking times vary by iron.","Carefully remove the waffle and serve with 2 tbsp maple syrup."],"cuisine":"Breakfast"},{"id":"scramble","name":"Breakfast Egg Scramble","slot":"Breakfast","emoji":"🍳","cal":350,"p":26,"c":15,"f":20,"ingredients":[["Eggs",3,"each"],["Bell peppers",0.5,"each"],["Spinach",1,"cup"],["Cheddar cheese",1,"oz"]],"steps":["Dice ½ bell pepper and rinse 1 cup spinach. Beat 3 eggs in a bowl; shred 1 oz cheddar.","Cook the diced pepper in a nonstick skillet over medium heat with 2 tbsp water for 2–3 minutes.","Add spinach and stir about 1 minute until wilted. Pour in the 3 beaten eggs.","Stir gently for 2–3 minutes until no liquid egg remains. Sprinkle 1 oz cheddar over the eggs and let melt for 30 seconds."],"cuisine":"Breakfast"},{"id":"parfait","name":"Yogurt Granola Parfait","slot":"Breakfast","emoji":"🍓","cal":330,"p":20,"c":47,"f":8,"ingredients":[["Greek yogurt",1,"cup"],["Granola",0.5,"cup"],["Strawberries",0.5,"cup"]],"steps":["Rinse, hull and slice ½ cup strawberries.","Spoon ½ cup of the 1 cup Greek yogurt into a bowl or glass.","Layer ¼ cup of the ½ cup granola and half the strawberries on top.","Add the remaining ½ cup yogurt, ¼ cup granola and the remaining strawberries. Serve immediately to keep the granola crisp."],"cuisine":"Breakfast"},{"id":"breakfastsand","name":"Breakfast Sandwich","slot":"Breakfast","emoji":"🥪","cal":430,"p":25,"c":38,"f":19,"ingredients":[["English muffin",1,"each"],["Eggs",1,"each"],["Cheddar cheese",1,"oz"],["Turkey slices",2,"oz"]],"steps":["Split and toast 1 English muffin. Measure 2 oz turkey slices and 1 oz cheddar.","Cook 1 egg in a nonstick skillet over medium-low heat for 2–3 minutes per side, until the egg is fully set.","Place the turkey and cheese on the toasted muffin, then add the hot cooked egg.","Close the sandwich and warm in the skillet for 30–60 seconds until the cheese softens."],"cuisine":"Breakfast"},{"id":"bowlmex","name":"Mexican Chicken Burrito Bowl","slot":"Lunch","emoji":"🥙","cal":570,"p":43,"c":61,"f":17,"ingredients":[["Chicken breast",6,"oz"],["Cooked rice",1,"cup"],["Black beans",0.5,"cup"],["Salsa",0.25,"cup"],["Lettuce",1,"cup"]],"steps":["Slice 6 oz chicken breast into strips. Drain and rinse ½ cup black beans; chop 1 cup lettuce.","Cook chicken in a nonstick skillet over medium heat for 7–10 minutes, turning until 165°F.","Warm 1 cup already-cooked rice and ½ cup black beans separately until steaming.","Put rice in a bowl, add chicken, beans and the 1 cup chopped lettuce. Spoon ¼ cup salsa across the top."],"cuisine":"Mexican"},{"id":"shrimpTacos","name":"Shrimp Tacos","slot":"Dinner","emoji":"🌮","cal":510,"p":34,"c":45,"f":22,"ingredients":[["Shrimp",6,"oz"],["Corn tortillas",3,"each"],["Cabbage",1,"cup"],["Lime",0.5,"each"],["Greek yogurt",2,"tbsp"]],"steps":["Pat dry 6 oz peeled, deveined shrimp. Shred 1 cup cabbage and cut ½ lime into wedges.","Heat a nonstick skillet over medium heat. Cook shrimp 2–3 minutes per side until opaque and firm, reaching 145°F if checking with a thermometer.","Warm 3 corn tortillas in a dry skillet for 15–30 seconds per side.","Divide the shrimp and 1 cup cabbage among tortillas. Drizzle with 2 tbsp Greek yogurt and squeeze lime over the top."],"cuisine":"Mexican"},{"id":"dumpling","name":"Vegetable Dumpling Bowls","slot":"Lunch","emoji":"🥟","cal":460,"p":16,"c":69,"f":13,"ingredients":[["Vegetable dumplings",6,"each"],["Cabbage",1,"cup"],["Carrots",0.5,"cup"],["Soy sauce",1,"tbsp"],["Sesame oil",1,"tsp"]],"steps":["Cook 6 vegetable dumplings according to their package, either steaming until hot or pan-cooking as directed.","Shred 1 cup cabbage and thinly slice ½ cup carrots.","Heat 1 tsp sesame oil in a skillet over medium heat. Add cabbage and carrots with 2 tbsp water; cook 3–5 minutes until tender-crisp.","Arrange the vegetables in a bowl, top with the hot dumplings and drizzle with 1 tbsp soy sauce."],"cuisine":"Chinese"},{"id":"orangeChicken","name":"Orange Chicken Rice","slot":"Dinner","emoji":"🍊","cal":640,"p":42,"c":76,"f":17,"ingredients":[["Chicken breast",6,"oz"],["Cooked rice",1,"cup"],["Orange juice",0.25,"cup"],["Soy sauce",1,"tbsp"],["Broccoli",1,"cup"]],"steps":["Dice 6 oz chicken breast and chop 1 cup broccoli into bite-size florets.","Cook chicken in a nonstick skillet over medium heat for 6–9 minutes, stirring, until 165°F.","Add broccoli with 2 tbsp water, cover and cook 3–4 minutes until tender-crisp.","Stir ¼ cup orange juice and 1 tbsp soy sauce into the skillet. Simmer 2–3 minutes to lightly reduce and coat the chicken.","Warm 1 cup cooked rice until steaming and serve with the orange chicken and broccoli."],"cuisine":"Chinese"},{"id":"teriyaki","name":"Teriyaki Salmon Rice Bowl","slot":"Dinner","emoji":"🍣","cal":610,"p":42,"c":64,"f":20,"ingredients":[["Salmon fillet",6,"oz"],["Cooked rice",1,"cup"],["Teriyaki sauce",2,"tbsp"],["Broccoli",1,"cup"]],"steps":["Heat oven to 400°F. Place a 6 oz salmon fillet on a parchment-lined baking sheet.","Brush the salmon with 1 tbsp of the 2 tbsp teriyaki sauce and bake 12–16 minutes, until the fish flakes and reaches 145°F.","Steam 1 cup broccoli with 2 tbsp water for 4–5 minutes until tender-crisp; warm 1 cup cooked rice until steaming.","Put the rice and broccoli in a bowl, place the cooked salmon on top, and drizzle with the remaining 1 tbsp teriyaki sauce from a clean container."],"cuisine":"Asian"},{"id":"greekwrap","name":"Greek Chicken Wrap","slot":"Lunch","emoji":"🫓","cal":500,"p":41,"c":41,"f":19,"ingredients":[["Chicken breast",5,"oz"],["Pita bread",1,"each"],["Cucumber",0.5,"each"],["Tomato",0.5,"each"],["Tzatziki",2,"tbsp"]],"steps":["Slice ½ cucumber and ½ tomato into small pieces. Warm 1 pita bread briefly until flexible.","Cook 5 oz chicken breast in a nonstick skillet over medium heat for 5–7 minutes per side, until 165°F. Rest 3 minutes, then slice thinly.","Spread 2 tbsp tzatziki across the warmed pita.","Add the sliced chicken, cucumber and tomato. Fold the pita securely and serve."],"cuisine":"Mediterranean"},{"id":"medbowl","name":"Mediterranean Chickpea Bowl","slot":"Dinner","emoji":"🥗","cal":550,"p":22,"c":70,"f":20,"ingredients":[["Chickpeas",1,"cup"],["Cooked rice",0.75,"cup"],["Cucumber",0.5,"each"],["Tomato",1,"each"],["Feta",1,"oz"],["Olive oil",1,"tbsp"]],"steps":["Drain and rinse 1 cup chickpeas. Dice ½ cucumber and 1 tomato.","Warm ¾ cup cooked rice and the chickpeas until steaming; they may be heated together in a small saucepan with 2 tbsp water.","Spoon the rice and chickpeas into a bowl and arrange the diced cucumber and tomato on top.","Crumble 1 oz feta over everything, then drizzle with 1 tbsp olive oil just before serving."],"cuisine":"Mediterranean"},{"id":"burgers","name":"Homemade Turkey Burgers","slot":"Dinner","emoji":"🍔","cal":570,"p":42,"c":46,"f":23,"ingredients":[["Ground turkey",6,"oz"],["Burger bun",1,"each"],["Lettuce",1,"cup"],["Tomato",0.5,"each"],["Potatoes",1,"cup"]],"steps":["Preheat oven to 425°F. Cut 1 cup potatoes into thin wedges; spread in a single layer on a parchment-lined pan.","Roast potatoes for 25–30 minutes, turning halfway, until tender and browned.","Shape the measured 6 oz ground turkey into one even-thickness patty, pressing a shallow indentation in the center so it cooks evenly; wash your hands after handling raw turkey. Cook in a nonstick skillet over medium heat for about 5–6 minutes per side until the center reaches 165°F.","Slice ½ tomato and prepare 1 cup lettuce. Toast 1 burger bun for 30–60 seconds.","Place the cooked turkey patty, lettuce and tomato on the bun and serve with roasted potato wedges."],"cuisine":"American"}]);recipes.push(...[{"id":"sesameChicken","name":"Sesame Chicken & Rice","slot":"Dinner","cuisine":"Chinese","emoji":"🍗","cal":550,"p":43,"c":64,"f":13,"ingredients":[["Chicken breast",6,"oz"],["Cooked rice",1,"cup"],["Broccoli",1,"cup"],["Soy sauce",1,"tbsp"],["Honey",1,"tbsp"],["Sesame seeds",1,"tsp"]],"steps":["Cut 6 oz chicken breast into bite-sized pieces and chop 1 cup broccoli.","Cook chicken in a nonstick skillet over medium-high heat for 6–9 minutes, stirring, until 165°F.","Add broccoli and 2 tbsp water. Cover 3 minutes, then uncover.","Mix 1 tbsp soy sauce and 1 tbsp honey and pour into the skillet; toss 1–2 minutes until the sauce lightly coats everything.","Warm 1 cup cooked rice and serve topped with the chicken-broccoli mixture and 1 tsp sesame seeds."]},{"id":"kungPao","name":"Kung Pao Chicken","slot":"Dinner","cuisine":"Chinese","emoji":"🥡","cal":620,"p":47,"c":66,"f":19,"ingredients":[["Chicken breast",6,"oz"],["Bell pepper",1,"each"],["Peanuts",2,"tbsp"],["Cooked rice",1,"cup"],["Soy sauce",1,"tbsp"],["Chili flakes",0.25,"tsp"]],"steps":["Dice 6 oz chicken breast and 1 bell pepper. Mix 1 tbsp soy sauce with ¼ tsp chili flakes.","Cook chicken in a nonstick skillet over medium-high heat for 6–9 minutes, stirring until 165°F.","Add the diced pepper and 2 tbsp water; stir-fry 3–4 minutes until softened.","Pour in the soy-chili mixture and toss 1 minute. Fold in 2 tbsp peanuts, keeping them separate if serving anyone with a peanut allergy.","Warm 1 cup already-cooked rice until steaming and serve the chicken mixture over it."]},{"id":"loMein","name":"Chicken Lo Mein","slot":"Lunch","cuisine":"Chinese","emoji":"🍜","cal":510,"p":43,"c":49,"f":15,"ingredients":[["Chicken breast",5,"oz"],["Egg noodles",2,"oz"],["Cabbage",1,"cup"],["Carrot",0.5,"each"],["Soy sauce",1,"tbsp"],["Sesame oil",1,"tsp"]],"steps":["Boil 2 oz dry egg noodles according to package instructions, usually 5–8 minutes; drain.","Cut 5 oz chicken breast into thin strips, shred 1 cup cabbage and slice ½ carrot into thin matchsticks.","Heat 1 tsp sesame oil in a large skillet over medium-high heat. Cook chicken for 6–9 minutes until 165°F.","Add cabbage and carrot with 2 tbsp water and cook 3–4 minutes until just tender.","Stir in drained noodles and 1 tbsp soy sauce. Toss 1–2 minutes until evenly coated and steaming."]},{"id":"beefNoodles","name":"Beef Noodle Stir-Fry","slot":"Dinner","cuisine":"Asian","emoji":"🍜","cal":565,"p":38,"c":56,"f":19,"ingredients":[["Lean beef",5,"oz"],["Rice noodles",2,"oz"],["Bell pepper",1,"each"],["Broccoli",1,"cup"],["Soy sauce",1,"tbsp"]],"steps":["Soak or boil 2 oz dry rice noodles according to their package, then drain.","Thinly slice 5 oz lean beef; slice 1 bell pepper and chop 1 cup broccoli.","Sear beef in a hot nonstick skillet over medium-high heat for 2–3 minutes per side; move it to a clean plate.","Add pepper and broccoli with 2 tbsp water, cover 3–4 minutes until crisp-tender.","Return beef and add cooked noodles plus 1 tbsp soy sauce. Toss 1–2 minutes until hot and combined."]},{"id":"thaiBasil","name":"Thai Basil Chicken","slot":"Dinner","cuisine":"Asian","emoji":"🌿","cal":560,"p":42,"c":57,"f":17,"ingredients":[["Ground chicken",6,"oz"],["Cooked rice",1,"cup"],["Basil",0.25,"cup"],["Garlic",2,"clove"],["Soy sauce",1,"tbsp"],["Bell pepper",0.5,"each"]],"steps":["Mince 2 cloves garlic, thinly slice ½ bell pepper and rinse ¼ cup basil.","Put 6 oz ground chicken in a nonstick skillet over medium-high heat. Break into small pieces and cook 5–7 minutes until 165°F.","Add the garlic and sliced pepper and stir-fry 2–3 minutes until softened.","Stir in 1 tbsp soy sauce, then add ¼ cup basil and cook another 30 seconds until wilted.","Warm 1 cup cooked rice until steaming and spoon the chicken mixture over it."]},{"id":"sweetSour","name":"Sweet & Sour Chicken","slot":"Lunch","cuisine":"Chinese","emoji":"🍍","cal":530,"p":42,"c":72,"f":9,"ingredients":[["Chicken breast",5,"oz"],["Pineapple chunks",0.5,"cup"],["Bell pepper",1,"each"],["Cooked rice",1,"cup"],["Rice vinegar",1,"tbsp"],["Ketchup",1,"tbsp"]],"steps":["Dice 5 oz chicken breast and 1 bell pepper. Drain ½ cup pineapple chunks.","Cook chicken in a nonstick skillet over medium heat for 6–9 minutes until 165°F.","Add pepper and 2 tbsp water, cover and cook 3 minutes.","Mix 1 tbsp rice vinegar with 1 tbsp ketchup. Add to the skillet along with ½ cup pineapple; toss for 2–3 minutes until hot and lightly glazed.","Warm 1 cup cooked rice until steaming and serve the chicken and pineapple over it."]},{"id":"beefTacos","name":"Ground Beef Tacos","slot":"Dinner","cuisine":"Mexican","emoji":"🌮","cal":505,"p":37,"c":43,"f":20,"ingredients":[["Lean ground beef",5,"oz"],["Corn tortillas",3,"each"],["Lettuce",1,"cup"],["Tomato",0.5,"each"],["Salsa",2,"tbsp"],["Taco seasoning",1,"tsp"]],"steps":["Break 5 oz lean ground beef into a nonstick skillet over medium heat. Cook 6–8 minutes until browned and at least 160°F; drain if needed.","Stir in 1 tsp taco seasoning and 2 tbsp water. Simmer 2 minutes so the seasoning coats the meat.","Shred 1 cup lettuce, dice ½ tomato and warm 3 corn tortillas in a dry skillet for 15–30 seconds per side.","Fill tortillas with the seasoned beef, lettuce and tomato, then top with 2 tbsp salsa."]},{"id":"chickenQuesa","name":"Chicken & Cheese Quesadillas","slot":"Lunch","cuisine":"Tex-Mex","emoji":"🫓","cal":545,"p":48,"c":49,"f":19,"ingredients":[["Chicken breast",5,"oz"],["Flour tortillas",2,"each"],["Cheddar cheese",1,"oz"],["Bell pepper",0.5,"each"],["Salsa",2,"tbsp"]],"steps":["Dice 5 oz chicken breast and ½ bell pepper. Shred 1 oz cheddar.","Cook chicken in a nonstick skillet over medium heat for 6–9 minutes, until 165°F. Add the pepper and cook 2 more minutes.","Place 1 flour tortilla in a dry skillet over medium-low heat. Scatter the cooked chicken, pepper and 1 oz cheddar over it; cover with the second tortilla.","Cook 2–3 minutes per side, flipping carefully, until both sides are golden and the cheese melts.","Slice into wedges and serve with 2 tbsp salsa."]},{"id":"steakFajitaBowl","name":"Steak Fajita Rice Bowl","slot":"Dinner","cuisine":"Tex-Mex","emoji":"🥩","cal":675,"p":51,"c":80,"f":17,"ingredients":[["Lean steak",6,"oz"],["Cooked rice",1,"cup"],["Bell pepper",1,"each"],["Onion",0.5,"each"],["Black beans",0.5,"cup"],["Fajita seasoning",1,"tsp"]],"steps":["Slice 6 oz lean steak, 1 bell pepper and ½ onion into thin strips. Drain ½ cup black beans.","Coat the steak with 1 tsp fajita seasoning. Sear in a nonstick skillet over medium-high heat for 2–3 minutes per side, to your preferred safe doneness; transfer to a plate.","Cook pepper and onion in the skillet with 2 tbsp water for 4–5 minutes until softened.","Warm 1 cup cooked rice and ½ cup black beans until steaming, then assemble in a bowl with the steak and vegetables."]},{"id":"chickenEnchilada","name":"Chicken Enchiladas","slot":"Dinner","cuisine":"Mexican","emoji":"🫔","cal":565,"p":51,"c":43,"f":21,"ingredients":[["Chicken breast",5,"oz"],["Corn tortillas",3,"each"],["Enchilada sauce",0.5,"cup"],["Monterey Jack cheese",1,"oz"],["Onion",0.25,"each"]],"steps":["Preheat oven to 375°F. Dice ¼ onion and shred 1 oz Monterey Jack cheese.","Cook 5 oz diced chicken breast in a nonstick skillet over medium heat for 7–10 minutes until 165°F; mix with the diced onion.","Spread 2 tbsp of the ½ cup enchilada sauce in a small baking dish. Warm 3 corn tortillas until flexible.","Divide cooked chicken among the tortillas, roll tightly and place seam-down. Pour on remaining enchilada sauce and sprinkle with 1 oz cheese.","Bake 15–20 minutes until bubbling and cheese melts. Rest for 3 minutes before serving."]},{"id":"beefBurrito","name":"Beef & Bean Burrito","slot":"Lunch","cuisine":"Tex-Mex","emoji":"🌯","cal":670,"p":42,"c":75,"f":23,"ingredients":[["Lean ground beef",5,"oz"],["Flour tortilla",1,"large"],["Black beans",0.5,"cup"],["Cooked rice",0.5,"cup"],["Salsa",2,"tbsp"],["Cheddar cheese",1,"oz"]],"steps":["Cook 5 oz lean ground beef in a nonstick skillet over medium heat for 6–8 minutes, breaking it apart, until 160°F; drain excess fat.","Drain ½ cup black beans. Warm the beans and ½ cup cooked rice until steaming.","Warm 1 large flour tortilla for 15–20 seconds until flexible; lay it flat.","Place cooked beef, warmed beans and rice down the center. Add 2 tbsp salsa and 1 oz cheddar.","Fold in both sides and roll tightly from the bottom. Toast seam-side down in a dry skillet for 1 minute if desired."]},{"id":"tacoSalad","name":"Tex-Mex Taco Salad","slot":"Lunch","cuisine":"Tex-Mex","emoji":"🥗","cal":525,"p":42,"c":57,"f":14,"ingredients":[["Lean ground turkey",5,"oz"],["Romaine lettuce",2,"cup"],["Black beans",0.5,"cup"],["Corn",0.5,"cup"],["Tomato",1,"each"],["Salsa",2,"tbsp"]],"steps":["Brown 5 oz lean ground turkey in a nonstick skillet over medium heat, breaking it apart, 6–9 minutes until 165°F.","Drain and rinse ½ cup black beans and ½ cup corn. Warm both until steaming.","Chop 2 cups romaine lettuce and dice 1 tomato; arrange together in a large bowl.","Top lettuce with cooked turkey, warm black beans and corn. Spoon 2 tbsp salsa over the salad and serve."]}]);const cookingGuides={"oats":{"prep":5,"rest":"Refrigerate at least 4 hours (ideally overnight)","steps":["Measure the oats, yogurt and milk into a covered container.","Stir thoroughly until no dry oats remain.","Refrigerate for at least 4 hours, ideally overnight.","Top with berries just before serving."]},"eggs":{"prep":5,"cook":8,"steps":["Slice the avocado and set it aside.","Place the whole-grain bread in a toaster and toast until the edges are golden and the center is crisp.","Cook the eggs to your preference in a lightly greased pan; avoid serving undercooked eggs to higher-risk eaters.","Layer avocado and eggs over the warm toast and serve."]},"smoothie":{"prep":5,"steps":["Peel the measured banana and cut it into thin rounds on a clean cutting board before adding it to the dish.","Pour milk into the blender, then add banana, protein powder and peanut butter.","Blend until smooth; add a little more milk if needed.","Pour into a glass and serve immediately."]},"chicken":{"prep":10,"cook":25,"steps":["Start cooking the brown rice according to the package directions.","Cut chicken into even pieces and season to taste.","Cook chicken in a skillet until its thickest part reaches 165°F (74°C).","Steam broccoli until tender; toss with olive oil.","Serve chicken and broccoli over rice."]},"wrap":{"prep":10,"steps":["Rinse the measured spinach under cool running water and pat dry with a clean towel before adding it to the recipe.","Spread hummus evenly over the tortilla, leaving a small border.","Layer turkey slices and spinach in the middle.","Fold the sides inward, roll tightly and slice to serve."]},"salad":{"prep":12,"steps":["Pour the measured chickpeas into a strainer, rinse under cool running water, and shake off excess water before using.","Wash and chop the vegetables listed in the ingredients.","Combine chickpeas and vegetables in a large bowl.","Add the listed dressing ingredients, toss and serve."]},"salmon":{"prep":10,"cook":25,"steps":["Preheat the oven to 425°F (220°C).","Cut the sweet potato into evenly sized pieces and toss with the listed oil.","Roast sweet potato until tender, usually 20–30 minutes depending on size.","Add the salmon to a separate baking tray; bake until the fish reaches 145°F (63°C).","Plate with the roasted sweet potato and remaining vegetables."]},"pasta":{"prep":10,"cook":20,"steps":["Bring a pot of water to a boil and cook the pasta according to package instructions.","Brown ground turkey in a skillet until it reaches 165°F (74°C).","Add the listed tomato sauce or seasonings and simmer briefly.","Drain pasta, combine with sauce and serve."]},"tofu":{"prep":12,"cook":12,"steps":["Drain and pat the tofu dry, then cube it.","Cut the vegetables into bite-size pieces.","Heat a skillet or wok with the listed oil and cook tofu until golden.","Add vegetables and cook until crisp-tender.","Toss with sauce and serve over the listed grains if included."]},"pancakes":{"prep":5,"cook":12,"steps":["Mix pancake mix, milk and egg until just combined; small lumps are fine.","Heat a lightly oiled nonstick griddle over medium heat.","Pour small rounds of batter and cook until bubbles form on top.","Flip and cook the other side until golden and the center is cooked through.","Measure the recipe's maple syrup portion and drizzle it over the warm pancakes or waffles just before serving."]},"omelet":{"prep":7,"cook":8,"steps":["Chop any vegetables and grate cheese if needed.","Crack the measured eggs into a mixing bowl and whisk with a fork until the yolks and whites are thoroughly combined.","Cook vegetables in a lightly oiled pan until softened.","Pour eggs over the vegetables and cook gently until set.","Add cheese, fold the omelet and serve."]},"frenchtoast":{"prep":7,"cook":10,"steps":["Whisk eggs, milk and any listed spices in a shallow bowl.","Heat a lightly buttered skillet over medium heat.","Dip each bread slice briefly in the egg mixture.","Cook both sides until golden and egg mixture is fully cooked.","Add toppings and serve warm."]},"waffles":{"prep":7,"cook":10,"steps":["Preheat and lightly grease the waffle iron.","Whisk waffle mix, milk and egg until combined.","Pour batter into the iron without overfilling.","Cook until the waffle is golden and cooked through, following your waffle iron instructions.","Measure the recipe's maple syrup portion and drizzle it over the warm pancakes or waffles just before serving."]},"scramble":{"prep":6,"cook":8,"steps":["Wash and chop bell pepper and spinach.","Crack the measured eggs into a clean mixing bowl and beat with a fork until the whites and yolks are evenly combined.","Cook peppers in a skillet until softened, then add spinach until wilted.","Add eggs and gently scramble until set.","Top with cheddar and serve."]},"parfait":{"prep":5,"steps":["Wash and slice strawberries.","Spoon half the Greek yogurt into a glass or bowl.","Layer granola and berries over the yogurt.","Repeat with remaining yogurt and toppings; serve right away to keep granola crunchy."]},"orangeChicken":{"prep":12,"cook":20,"steps":["Cook rice according to its package directions.","Cut chicken into even pieces and cook in a hot pan until it reaches 165°F (74°C).","Whisk orange juice and soy sauce; add to the pan and simmer until slightly thickened.","Steam broccoli until tender.","Serve glazed chicken with rice and broccoli."]},"shrimpTacos":{"prep":12,"cook":8,"steps":["Shred cabbage and cut lime into wedges.","Mix Greek yogurt with lime juice for a quick sauce.","Cook shrimp in a hot skillet until opaque and firm; shrimp should reach 145°F (63°C).","Warm tortillas, fill with shrimp and cabbage, then drizzle with sauce."]},"bowlmex":{"prep":10,"cook":20,"steps":["Cook the rice according to package directions.","Season chicken and cook until it reaches 165°F (74°C).","Drain and rinse the measured black beans, warm them in a saucepan until steaming, and rinse and dry the lettuce.","Build bowls with rice, chicken, beans, lettuce and salsa."]}};recipes.forEach(r=>{if(cookingGuides[r.id])Object.assign(r,cookingGuides[r.id])});Object.entries({"burrito":{"prep":8,"cook":12,"steps":["Dice potatoes into small pieces and cook in a skillet until tender and browned.","Beat eggs and cook until set.","Warm the tortilla and layer the potatoes, eggs and cheese.","Roll the tortilla tightly and serve warm."]},"bagel":{"prep":5,"cook":7,"steps":["Slice and toast the bagel.","Continue cooking over medium-low heat until the egg white is opaque and the yolk reaches your preferred doneness.","Warm turkey slices if desired.","Layer egg, turkey and cheese inside the bagel."]},"cereal":{"prep":3,"steps":["Peel the banana, place it on a clean cutting board, and slice it crosswise into thin, even rounds.","Pour cereal into a bowl.","Add milk and top with banana."]},"tacos":{"prep":12,"cook":15,"steps":["Dice onion and chop cilantro; cut lime into wedges.","Season chicken, then cook until it reaches 165°F (74°C).","Slice or shred the cooked chicken.","Warm tortillas and fill with chicken, onion and cilantro.","Squeeze lime over the tacos before serving."]},"quesadilla":{"prep":5,"cook":10,"steps":["Drain and rinse black beans.","Add beans and cheese to half of each tortilla, then fold closed.","Cook in a skillet over medium heat until golden on both sides and cheese has melted.","Slice into wedges and serve with salsa."]},"friedrice":{"prep":12,"cook":15,"steps":["Cook rice ahead of time according to package directions; cooled rice works best.","Cut chicken into bite-size pieces and cook to 165°F (74°C).","Cook vegetables in a large skillet until softened.","Scramble the egg until set, then add rice and chicken.","Add soy sauce and toss until everything is hot."]},"noodles":{"prep":7,"cook":10,"steps":["Cook noodles according to package directions and drain.","Mince garlic and mix with the listed sesame sauce ingredients.","Gently heat the sauce in a skillet, taking care not to burn garlic.","Toss the noodles with sauce until evenly coated and serve."]},"soup":{"prep":12,"cook":25,"steps":["Chop vegetables into even pieces.","Bring broth to a gentle simmer and add vegetables.","Add chicken and simmer until the center reaches 165°F (74°C).","Add noodles and cook until tender according to package directions.","Taste, season and serve hot."]},"sandwich":{"prep":8,"cook":15,"steps":["Prepare and wash any sandwich vegetables.","Season chicken and cook until the center reaches 165°F (74°C).","Toast bread or bun if desired.","Layer chicken and toppings, close sandwich and serve."]},"fajitas":{"prep":12,"cook":15,"steps":["Slice peppers and onion into strips.","Cut chicken into even strips and season.","Cook chicken in a hot skillet until it reaches 165°F (74°C).","Add peppers and onion; cook until tender-crisp.","Serve with warmed tortillas."]},"enchiladas":{"prep":12,"cook":20,"steps":["Preheat the oven to 375°F (190°C).","Drain beans and place a portion into each tortilla.","Roll filled tortillas seam-side down in a baking dish.","Cover with enchilada sauce and cheese.","Bake about 15–20 minutes until heated through and cheese bubbles."]},"stirfry":{"prep":12,"cook":14,"steps":["Cook rice according to package directions.","Slice chicken and vegetables into even pieces.","Cook chicken in a hot pan until it reaches 165°F (74°C).","Add vegetables and stir-fry until crisp-tender.","Add ginger and soy sauce; toss and serve over rice."]},"beefbroccoli":{"prep":10,"cook":15,"steps":["Prepare rice following package directions.","Slice beef thinly against the grain and chop broccoli.","Sear beef in batches in a hot skillet.","Add broccoli, garlic and sauce; cook until broccoli is tender and beef is safely cooked.","Spoon the cooked mixture over the measured portion of hot cooked rice and serve immediately while everything is warm."]},"spaghetti":{"prep":15,"cook":25,"steps":["Cook spaghetti in boiling water according to package directions.","Combine the listed meatball ingredients and form equal-size balls.","Cook meatballs thoroughly; ground beef should reach 160°F (71°C), or poultry 165°F (74°C).","Warm tomato sauce and simmer cooked meatballs in it.","Drain pasta and serve topped with meatballs and sauce."]},"chickenparm":{"prep":15,"cook":25,"steps":["Preheat the oven to 400°F (205°C).","Cook pasta according to package directions.","Coat chicken using the listed breading ingredients.","Bake or pan-cook chicken until its center reaches 165°F (74°C).","Top with tomato sauce and cheese and heat until melted.","Serve with cooked pasta."]},"breakfastsand":{"prep":5,"cook":8,"steps":["Split and toast the English muffin.","Cook egg in a skillet until set.","Warm turkey slices if desired.","Add egg, turkey and cheddar to the muffin, then serve."]},"dumpling":{"prep":8,"cook":12,"steps":["Cook dumplings according to the package's cooking instructions.","Rinse the cabbage and carrots, then slice into thin bite-sized strips on a clean cutting board.","Sauté vegetables with sesame oil until tender-crisp.","Serve dumplings on top of vegetables and drizzle with soy sauce."]},"teriyaki":{"prep":8,"cook":20,"steps":["Cook rice according to package directions.","Preheat oven to 400°F (205°C).","Place salmon on a baking tray and brush with teriyaki sauce.","Bake until the salmon reaches 145°F (63°C).","Steam broccoli and serve salmon alongside rice and vegetables."]},"greekwrap":{"prep":10,"cook":12,"steps":["Rinse the cucumber and tomato, then cut into bite-sized pieces on a clean cutting board.","Cook chicken until the center reaches 165°F (74°C), then slice.","Warm pita lightly if desired.","Fill pita with chicken, cucumber, tomato and tzatziki."]},"medbowl":{"prep":10,"steps":["Drain and rinse chickpeas.","Prepare cooked rice and let cool slightly.","Dice cucumber and tomato.","Arrange rice, chickpeas and vegetables in bowls.","Top with feta and olive oil; toss before eating."]},"burgers":{"prep":12,"cook":25,"steps":["Preheat oven to 425°F (220°C).","Cut potatoes into wedges and roast until tender, about 20–30 minutes.","Form ground turkey into patties without overworking.","Cook patties to 165°F (74°C).","Assemble with bun, lettuce and tomato and serve with roasted potatoes."]}}).forEach(([id,guide])=>{const r=recipes.find(x=>x.id===id);if(r)Object.assign(r,guide)});recipes.push(...[{"id":"homeCfs","name":"Chicken Fried Steak","slot":"Dinner","cuisine":"American","emoji":"🍽️","cal":690,"p":40,"c":54,"f":34,"ingredients":[["Cube steak",6,"oz"],["All-purpose flour",0.25,"cup"],["Egg",1,"each"],["Milk",0.25,"cup"],["Cooking oil",1,"tbsp"],["Black pepper",0.25,"tsp"]],"steps":["Pat 6 oz cube steak dry and season with ¼ tsp black pepper. Put ¼ cup flour on a plate and beat 1 egg in a separate bowl.","Dip steak in flour, then egg, then flour again, pressing so the coating adheres. Reserve 1 tbsp of unused flour for gravy, discarding flour that touched raw meat.","Heat 1 tbsp cooking oil in a skillet over medium heat. Cook coated steak approximately 4–5 minutes per side, reducing heat if the crust darkens too fast; check the center reaches 145°F and rest 3 minutes.","Move steak to a plate. Whisk the reserved clean 1 tbsp flour into the skillet drippings for 30 seconds, then slowly add ¼ cup milk and simmer 2–3 minutes until the gravy coats a spoon.","Pour gravy over the rested steak and serve hot."]},{"id":"homeBurgers","name":"Hamburgers","slot":"Dinner","cuisine":"American","emoji":"🍔","cal":590,"p":39,"c":40,"f":29,"ingredients":[["Ground beef",6,"oz"],["Hamburger bun",1,"each"],["Lettuce",1,"cup"],["Tomato",0.5,"each"],["Cheddar cheese",1,"oz"]],"steps":["Shape 6 oz ground beef into one patty roughly ¾ inch thick; make a small thumb indentation in its center.","Cook the patty in a nonstick skillet over medium heat for around 4–6 minutes per side, until it reaches 160°F in the center.","Place 1 oz cheddar cheese on the patty during the last minute of cooking and cover briefly to melt.","Slice ½ tomato and prepare 1 cup lettuce. Warm 1 hamburger bun cut-side down in the skillet for 30 seconds.","Place the cooked burger on the bun, top with lettuce and tomato, and serve."]},{"id":"homeTaterTot","name":"Tater Tot Casserole","slot":"Dinner","cuisine":"American","emoji":"🥘","cal":650,"p":33,"c":49,"f":35,"ingredients":[["Ground beef",5,"oz"],["Frozen tater tots",1,"cup"],["Cream of mushroom soup",0.5,"cup"],["Cheddar cheese",1,"oz"],["Onion",0.25,"each"]],"steps":["Preheat the oven to 400°F. Finely dice ¼ onion.","Brown 5 oz ground beef with the diced onion in a nonstick skillet over medium-high heat for 6–8 minutes, breaking into crumbs, until the beef reaches 160°F; drain excess fat.","Stir ½ cup cream of mushroom soup into the cooked beef and spread the mixture in a small oven-safe dish.","Arrange 1 cup frozen tater tots in an even layer over the beef mixture.","Bake for 20–25 minutes, until the tots are hot and golden. Sprinkle 1 oz cheddar cheese over the top and bake 3–5 minutes more until melted."]}]);recipes.push(...[{"id":"southSmotheredPork","name":"Smothered Pork Chops","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":620,"p":43,"c":38,"f":32,"ingredients":[["Pork chop",6,"oz"],["Onion",0.5,"each"],["All-purpose flour",2,"tbsp"],["Chicken broth",0.75,"cup"],["Milk",0.25,"cup"],["Mashed potatoes",1,"cup"]],"steps":["Slice ½ onion thinly. Pat 6 oz pork chop dry and coat lightly with 1 tbsp of the 2 tbsp all-purpose flour; reserve the other 1 tbsp for gravy.","Heat a nonstick skillet over medium-high heat. Brown the pork chop for 3 minutes per side, then transfer to a plate; it will finish cooking in the gravy.","Add the sliced ½ onion and 2 tbsp water to the skillet. Cook 4–5 minutes, stirring until softened.","Sprinkle the reserved 1 tbsp flour over the onion and stir for 1 minute. Slowly whisk in ¾ cup chicken broth and ¼ cup milk until smooth.","Return the pork chop to the gravy. Cover and simmer gently 6–10 minutes, until it reaches 145°F; rest the pork for 3 minutes.","Warm 1 cup prepared mashed potatoes until steaming. Spoon the pork and onion gravy over the potatoes."]},{"id":"southFriedChicken","name":"Southern Fried Chicken","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":680,"p":45,"c":42,"f":35,"ingredients":[["Chicken thighs",8,"oz"],["Buttermilk",0.5,"cup"],["All-purpose flour",0.75,"cup"],["Paprika",0.5,"tsp"],["Cooking oil",2,"tbsp"]],"steps":["Place 8 oz chicken thighs in ½ cup buttermilk; refrigerate at least 30 minutes. Drain off excess buttermilk.","In a shallow bowl, mix ¾ cup all-purpose flour with ½ tsp paprika. Press each piece of chicken firmly into the flour coating.","Heat 2 tbsp cooking oil in a nonstick skillet over medium heat until shimmering, not smoking. This is shallow pan-frying, not deep-frying.","Add the coated chicken without crowding the pan. Cook approximately 6–8 minutes per side, turning as needed; reduce heat if the coating browns too fast.","Check the thickest part with a food thermometer. Chicken must reach 165°F. Rest 3 minutes before serving."]},{"id":"southChickenDumplings","name":"Chicken and Dumplings","slot":"Dinner","cuisine":"Southern","emoji":"🥣","cal":590,"p":39,"c":62,"f":20,"ingredients":[["Chicken breast",6,"oz"],["Chicken broth",2,"cup"],["Carrots",0.5,"cup"],["Celery",0.5,"cup"],["Biscuit dough",4,"oz"],["Milk",0.25,"cup"]],"steps":["Cut 6 oz chicken breast into bite-sized pieces. Slice ½ cup carrots and ½ cup celery.","Add 2 cups chicken broth, the chicken, carrots and celery to a saucepan. Bring to a gentle simmer over medium heat.","Cover and simmer 12–15 minutes, until the vegetables soften and the chicken reaches 165°F.","Cut 4 oz biscuit dough into small spoon-sized dumplings. Stir ¼ cup milk into the simmering broth.","Drop the dough pieces onto the gently bubbling broth, leaving space between them. Cover and simmer 10–12 minutes without vigorous stirring.","Cut one dumpling in half to ensure the center is fully cooked, not raw or doughy. Ladle the chicken, vegetables, broth and dumplings into a bowl."]},{"id":"southChickenGravy","name":"Chicken and Gravy over Mashed Potatoes","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":610,"p":44,"c":53,"f":24,"ingredients":[["Chicken breast",6,"oz"],["Chicken broth",1,"cup"],["Milk",0.25,"cup"],["All-purpose flour",1.5,"tbsp"],["Mashed potatoes",1.25,"cup"]],"steps":["Cut 6 oz chicken breast into bite-sized pieces. Put a skillet over medium heat.","Add the chicken and 2 tbsp of the 1 cup chicken broth to the skillet. Cook 6–9 minutes, stirring, until the chicken reaches 165°F.","Move chicken to a plate. Whisk 1½ tbsp all-purpose flour into ¼ cup cold milk until no lumps remain.","Pour the remaining chicken broth into the skillet and bring to a simmer. Slowly whisk in the flour-milk mixture and cook 3–5 minutes until thickened.","Return chicken to the gravy and heat 1–2 minutes. Warm 1¼ cups prepared mashed potatoes until steaming; spoon chicken and gravy over the potatoes."]},{"id":"southChickenRice","name":"Southern Chicken and Rice","slot":"Dinner","cuisine":"Southern","emoji":"🍚","cal":560,"p":42,"c":62,"f":15,"ingredients":[["Chicken thighs",6,"oz"],["Long-grain rice",0.75,"cup"],["Chicken broth",1.5,"cup"],["Onion",0.25,"each"],["Celery",0.5,"cup"]],"steps":["Dice ¼ onion and chop ½ cup celery. Cut 6 oz chicken thighs into bite-sized pieces.","In a covered saucepan over medium heat, cook chicken with the onion and celery for 5–6 minutes, stirring often.","Stir in ¾ cup uncooked long-grain rice and pour in 1½ cups chicken broth. Bring to a gentle boil.","Cover, reduce heat to low, and simmer 18–22 minutes, or until rice is tender and liquid is absorbed. Add a splash of water if needed.","Check chicken reaches 165°F and rice is fully cooked. Let stand covered for 5 minutes, fluff with a fork, and serve."]},{"id":"southChickenSpaghetti","name":"Southern Chicken Spaghetti","slot":"Dinner","cuisine":"Southern","emoji":"🍝","cal":640,"p":43,"c":65,"f":23,"ingredients":[["Chicken breast",5,"oz"],["Spaghetti",3,"oz"],["Cream of chicken soup",0.5,"cup"],["Diced tomatoes with green chiles",0.5,"cup"],["Cheddar cheese",1.5,"oz"]],"steps":["Preheat oven to 375°F. Cook 3 oz dry spaghetti in boiling water according to the package, usually 8–12 minutes; drain.","Cut 5 oz chicken breast into small pieces and cook in a nonstick skillet over medium heat for 7–10 minutes until it reaches 165°F.","In a small baking dish, stir together ½ cup cream of chicken soup and ½ cup diced tomatoes with green chiles.","Fold in the cooked chicken and spaghetti until well coated. Sprinkle 1½ oz shredded cheddar cheese evenly on top.","Bake uncovered for 15–20 minutes until hot and bubbly. Let rest 3 minutes before serving."]},{"id":"southBroccoliRice","name":"Chicken Broccoli Rice Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":610,"p":42,"c":58,"f":23,"ingredients":[["Chicken breast",5,"oz"],["Cooked rice",1,"cup"],["Broccoli",1,"cup"],["Cream of chicken soup",0.5,"cup"],["Cheddar cheese",1.5,"oz"]],"steps":["Preheat the oven to 375°F. Chop 5 oz chicken breast into small pieces and cut 1 cup broccoli into small florets.","Cook chicken in a skillet over medium heat for 7–10 minutes until it reaches 165°F. Steam the broccoli with 2 tbsp water for 3–4 minutes until just tender.","Mix 1 cup already-cooked rice, cooked chicken, steamed broccoli and ½ cup cream of chicken soup in a baking dish.","Sprinkle 1½ oz shredded cheddar evenly over the mixture.","Bake uncovered for 15–20 minutes until bubbling and hot throughout. Let rest 3 minutes before serving."]},{"id":"southPotPie","name":"Homestyle Chicken Pot Pie","slot":"Dinner","cuisine":"Southern","emoji":"🥧","cal":650,"p":37,"c":61,"f":29,"ingredients":[["Chicken breast",5,"oz"],["Mixed vegetables",1,"cup"],["Chicken broth",0.75,"cup"],["Milk",0.25,"cup"],["Pie crust",1,"each"]],"steps":["Preheat oven to 400°F. Cut 5 oz chicken breast into small pieces.","In a saucepan over medium heat, cook chicken with ¼ cup of the ¾ cup chicken broth for 7–10 minutes until the chicken reaches 165°F.","Add 1 cup mixed vegetables, the remaining ½ cup broth, and ¼ cup milk. Bring to a simmer and cook 3–5 minutes; the filling will be saucy.","Pour filling into an oven-safe pie dish. Cover with 1 pie crust, seal the edge, and cut 2 small steam vents in the top.","Bake 25–35 minutes, or until the crust is deeply golden and the filling bubbles through the vents. Let stand 5–10 minutes before slicing."]},{"id":"southDressingBake","name":"Chicken and Dressing Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":630,"p":40,"c":60,"f":25,"ingredients":[["Chicken breast",5,"oz"],["Cornbread stuffing mix",1.25,"cup"],["Chicken broth",1,"cup"],["Cream of chicken soup",0.5,"cup"],["Onion",0.25,"each"]],"steps":["Preheat oven to 375°F. Dice ¼ onion and chop 5 oz chicken breast.","Cook the chicken and onion in a nonstick skillet over medium heat for 8–10 minutes, until chicken reaches 165°F.","In a bowl, mix 1¼ cups cornbread stuffing mix with 1 cup chicken broth. Wait 3 minutes for the crumbs to absorb the broth.","Stir ½ cup cream of chicken soup into the cooked chicken. Spread this mixture in a small baking dish and cover evenly with the moistened stuffing.","Bake uncovered for 20–25 minutes, until piping hot and the dressing is lightly browned on top. Rest 3 minutes before serving."]},{"id":"southRanchChicken","name":"Creamy Ranch Chicken","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":590,"p":47,"c":28,"f":31,"ingredients":[["Chicken breast",6,"oz"],["Cream cheese",1.5,"oz"],["Ranch seasoning",1,"tbsp"],["Chicken broth",0.5,"cup"],["Green beans",1,"cup"]],"steps":["Cut 6 oz chicken breast into even pieces. Stir 1 tbsp ranch seasoning into ½ cup chicken broth.","Cook the chicken in a skillet over medium heat for about 4 minutes on each side until lightly browned.","Pour in the seasoned broth, cover and simmer gently for 5–8 minutes until chicken reaches 165°F.","Reduce heat to low. Stir in 1½ oz cream cheese in small pieces until the sauce is creamy, about 2–3 minutes. Do not boil hard.","Steam 1 cup green beans with a splash of water for 4–6 minutes until tender. Serve the ranch chicken and sauce alongside the beans."]},{"id":"southBbqChicken","name":"Honey BBQ Chicken","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":580,"p":45,"c":54,"f":18,"ingredients":[["Chicken breast",6,"oz"],["BBQ sauce",0.25,"cup"],["Honey",1,"tbsp"],["Baked beans",0.75,"cup"],["Coleslaw",0.5,"cup"]],"steps":["Preheat oven to 400°F. Place 6 oz chicken breast in a small baking dish.","Mix ¼ cup BBQ sauce and 1 tbsp honey in a bowl. Spoon half over the chicken, reserving half in a clean bowl.","Bake chicken 18–25 minutes, depending on thickness, until the center reaches 165°F.","Warm the reserved sauce separately in a small saucepan until it comes to a simmer; spoon over the cooked chicken. Never reuse sauce that touched raw chicken without boiling it.","Heat ¾ cup prepared baked beans until steaming. Serve with the chicken and ½ cup prepared coleslaw."]},{"id":"southTendersGravy","name":"Chicken Tenders with Country Gravy","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":690,"p":43,"c":61,"f":30,"ingredients":[["Chicken tenderloins",6,"oz"],["All-purpose flour",0.5,"cup"],["Milk",0.75,"cup"],["Cooking oil",1.5,"tbsp"],["Mashed potatoes",1,"cup"]],"steps":["Slice 6 oz chicken tenderloins into even strips. Set out ½ cup flour; reserve 1 tbsp of clean, unused flour for gravy.","Coat the chicken with the remaining flour. Heat 1½ tbsp cooking oil over medium heat and pan-fry chicken 4–6 minutes per side, until crisp and 165°F; transfer to a plate.","Lower heat. Whisk the reserved clean 1 tbsp flour into pan drippings for 1 minute. Slowly whisk in ¾ cup milk, simmer 3–5 minutes until thick.","Warm 1 cup prepared mashed potatoes until steaming. Serve chicken with the country gravy and potatoes."]},{"id":"southBeefTips","name":"Beef Tips and Gravy","slot":"Dinner","cuisine":"Southern","emoji":"🥩","cal":640,"p":43,"c":50,"f":28,"ingredients":[["Beef sirloin tips",6,"oz"],["Onion",0.5,"each"],["Beef broth",1,"cup"],["All-purpose flour",1.5,"tbsp"],["Mashed potatoes",1,"cup"]],"steps":["Slice ½ onion. Cut 6 oz beef sirloin tips into roughly 1-inch pieces.","Heat a skillet over medium-high heat and sear the beef 2–3 minutes per side until browned; transfer to a plate.","Cook the sliced onion in the same skillet for 4 minutes, stirring. Sprinkle in 1½ tbsp flour and stir for 1 minute.","Slowly pour in 1 cup beef broth while whisking. Return beef to the skillet, cover and simmer gently 10–15 minutes until cooked through and tender; stir occasionally.","Warm 1 cup prepared mashed potatoes until steaming. Spoon the beef tips and gravy over the potatoes."]},{"id":"southSalisbury","name":"Salisbury Steak with Onion Gravy","slot":"Dinner","cuisine":"Southern","emoji":"🥩","cal":650,"p":40,"c":42,"f":35,"ingredients":[["Ground beef",6,"oz"],["Onion",0.5,"each"],["Beef broth",0.75,"cup"],["Breadcrumbs",0.25,"cup"],["Mashed potatoes",1,"cup"]],"steps":["Finely dice ½ onion; set half aside for the gravy. Combine 6 oz ground beef, ¼ cup breadcrumbs and half the onion; shape into one thick oval patty.","Brown the patty in a skillet over medium heat for 4–5 minutes per side. Remove to a plate; it will finish cooking in gravy.","Cook the reserved onion in the skillet with 2 tbsp water for 3–4 minutes, until softened.","Add ¾ cup beef broth, scraping up browned bits. Return the patty, cover and simmer 5–8 minutes until the center reaches 160°F.","Warm 1 cup prepared mashed potatoes until steaming. Serve the patty with its onion pan sauce over the potatoes."]},{"id":"southMeatloaf","name":"Homestyle Meatloaf and Mashed Potatoes","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":670,"p":42,"c":55,"f":31,"ingredients":[["Ground beef",6,"oz"],["Breadcrumbs",0.25,"cup"],["Egg",1,"each"],["Ketchup",2,"tbsp"],["Mashed potatoes",1,"cup"]],"steps":["Preheat oven to 375°F. In a bowl combine 6 oz ground beef, ¼ cup breadcrumbs and 1 egg; mix gently until incorporated.","Shape the mixture into a compact loaf about 1½ inches thick in a small baking dish.","Spread 2 tbsp ketchup over the top of the loaf.","Bake 25–35 minutes, checking the center with a thermometer until it reaches 160°F. The exact time depends on loaf thickness.","Let meatloaf rest 5 minutes before slicing. Heat 1 cup prepared mashed potatoes until steaming and serve alongside."]},{"id":"southHamburgerSteak","name":"Hamburger Steak with Onion Gravy","slot":"Dinner","cuisine":"Southern","emoji":"🥩","cal":620,"p":41,"c":35,"f":35,"ingredients":[["Ground beef",6,"oz"],["Onion",0.5,"each"],["Beef broth",0.75,"cup"],["All-purpose flour",1,"tbsp"],["Green beans",1,"cup"]],"steps":["Form 6 oz ground beef into an oval patty and slice ½ onion thinly.","Brown patty in a nonstick skillet over medium heat for 4 minutes per side; set aside.","Cook the sliced onion in the skillet for 4 minutes. Stir in 1 tbsp all-purpose flour for 1 minute, then gradually whisk in ¾ cup beef broth.","Return the patty and simmer covered for 5–8 minutes until the center reaches 160°F. Steam 1 cup green beans for 4–6 minutes and serve with the gravy."]},{"id":"southCubeSteak","name":"Country Cube Steak with Gravy","slot":"Dinner","cuisine":"Southern","emoji":"🥩","cal":630,"p":42,"c":39,"f":33,"ingredients":[["Cube steak",6,"oz"],["All-purpose flour",0.25,"cup"],["Onion",0.5,"each"],["Beef broth",1,"cup"],["Mashed potatoes",1,"cup"]],"steps":["Pat 6 oz cube steak dry and press into ¼ cup flour, reserving only unused flour for gravy.","Sear steak in a nonstick skillet over medium heat for 3–4 minutes per side until browned; move to a plate.","Cook ½ sliced onion in the skillet with 2 tbsp water for 4 minutes. Add 1 cup beef broth and bring to a simmer.","Return steak and simmer covered 10–15 minutes until tender and reaches at least 145°F; rest 3 minutes. Warm 1 cup mashed potatoes until steaming and serve with the gravy."]},{"id":"southPotRoast","name":"Sunday Pot Roast","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":650,"p":46,"c":48,"f":30,"ingredients":[["Chuck roast",6,"oz"],["Potatoes",1,"cup"],["Carrots",1,"cup"],["Onion",0.5,"each"],["Beef broth",1,"cup"]],"steps":["Preheat the oven to 300°F. Cut 6 oz chuck roast into 2–3 large chunks. Chop 1 cup potatoes, 1 cup carrots and ½ onion into even pieces.","Heat an oven-safe lidded pot over medium-high heat. Brown the beef on each side for 2–3 minutes; add 2 tbsp water if needed to prevent sticking.","Add 1 cup beef broth and the chopped onion. Cover tightly and transfer the pot to the oven.","Braise the beef for 1½ hours, checking that some liquid remains. Add the potatoes and carrots around the meat.","Cover and cook another 45–75 minutes until the beef pulls apart easily with a fork and the vegetables are tender. Add a little water if the pot becomes dry.","Let stand 5 minutes, then spoon the beef, vegetables and cooking juices into a bowl."]},{"id":"southMississippiRoast","name":"Mississippi Pot Roast","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":690,"p":47,"c":35,"f":40,"ingredients":[["Chuck roast",6,"oz"],["Pepperoncini",4,"each"],["Ranch seasoning",1,"tbsp"],["Beef broth",0.5,"cup"],["Potatoes",1,"cup"]],"steps":["Preheat oven to 300°F. Put 6 oz chuck roast in a small covered ovenproof pot.","Scatter 4 pepperoncini around the beef, sprinkle with 1 tbsp ranch seasoning and add ½ cup beef broth.","Cover tightly and braise for 2–3 hours until beef easily separates with a fork; add a splash of water if the pot dries.","Cut 1 cup potatoes into chunks and add for the final 35–45 minutes until fork-tender. Shred beef into the cooking juices and serve with potatoes."]},{"id":"southBeefStew","name":"Country Beef Stew","slot":"Dinner","cuisine":"Southern","emoji":"🍲","cal":560,"p":39,"c":55,"f":21,"ingredients":[["Stew beef",6,"oz"],["Potatoes",1,"cup"],["Carrots",1,"cup"],["Onion",0.5,"each"],["Beef broth",2,"cup"]],"steps":["Cut 6 oz stew beef into 1-inch pieces. Chop 1 cup potatoes, 1 cup carrots and ½ onion into even chunks.","Brown beef in a heavy pot over medium-high heat for 2–3 minutes per side; stir in the chopped onion for 2 minutes.","Pour in 2 cups beef broth, bring to a low boil and reduce heat to a gentle simmer. Cover and cook 60–90 minutes, until beef starts to soften.","Add 1 cup potatoes and 1 cup carrots. Cover and simmer another 25–35 minutes until vegetables are fork-tender and the beef is easily pierced with a fork.","Let stew cool for 3–5 minutes before serving. Add a little water during cooking if the liquid level gets too low."]},{"id":"southGroundBeefGravy","name":"Ground Beef and Gravy over Mashed Potatoes","slot":"Dinner","cuisine":"Southern","emoji":"🥔","cal":650,"p":38,"c":55,"f":31,"ingredients":[["Ground beef",5,"oz"],["Onion",0.25,"each"],["Beef broth",0.75,"cup"],["All-purpose flour",1,"tbsp"],["Mashed potatoes",1.25,"cup"]],"steps":["Finely dice ¼ onion. Brown 5 oz ground beef with the onion in a skillet over medium heat for 6–8 minutes, breaking up the meat until it reaches 160°F.","Sprinkle 1 tbsp flour into the cooked meat and stir for 1 minute.","Gradually stir in ¾ cup beef broth and simmer 3–5 minutes, stirring until it thickens to gravy.","Warm 1¼ cups prepared mashed potatoes until steaming. Spoon beef gravy over potatoes."]},{"id":"southHamburgerPotato","name":"Hamburger Potato Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":680,"p":38,"c":57,"f":34,"ingredients":[["Ground beef",5,"oz"],["Potatoes",1.5,"cup"],["Cream of mushroom soup",0.5,"cup"],["Cheddar cheese",1.5,"oz"],["Onion",0.25,"each"]],"steps":["Preheat oven to 375°F. Thinly slice 1½ cups potatoes and dice ¼ onion.","Brown 5 oz ground beef and the diced onion in a skillet for 6–8 minutes until beef reaches 160°F.","Layer the sliced potatoes and cooked beef in a small covered baking dish. Spread ½ cup cream of mushroom soup over the layers and add ¼ cup water.","Cover and bake 40–50 minutes until potatoes are fork-tender. Uncover, top with 1½ oz cheddar and bake 5 minutes to melt."]},{"id":"southCowboyCass","name":"Cowboy Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":700,"p":37,"c":65,"f":34,"ingredients":[["Ground beef",5,"oz"],["Corn",0.5,"cup"],["Cream of mushroom soup",0.5,"cup"],["Cheddar cheese",1.5,"oz"],["Frozen tater tots",1,"cup"]],"steps":["Preheat oven to 400°F. Brown 5 oz ground beef in a nonstick skillet for 6–8 minutes until 160°F.","Mix the cooked beef with ½ cup corn and ½ cup cream of mushroom soup; spread in a small baking dish.","Sprinkle 1½ oz cheddar over the beef, then arrange 1 cup frozen tater tots on top.","Bake uncovered 25–30 minutes until tots are crisp, cheese melts and filling bubbles."]},{"id":"southSloppyJoe","name":"Homestyle Sloppy Joes","slot":"Dinner","cuisine":"Southern","emoji":"🥪","cal":590,"p":35,"c":58,"f":24,"ingredients":[["Ground beef",5,"oz"],["Hamburger bun",1,"each"],["Tomato sauce",0.5,"cup"],["Brown sugar",1,"tsp"],["Onion",0.25,"each"]],"steps":["Finely chop ¼ onion. Brown 5 oz ground beef and onion over medium heat for 6–8 minutes until 160°F; drain excess fat.","Stir in ½ cup tomato sauce and 1 tsp brown sugar.","Reduce heat and simmer uncovered 8–10 minutes, stirring until the sauce thickens around the beef.","Toast 1 hamburger bun and spoon the hot beef mixture onto it."]},{"id":"southBaconBurger","name":"Bacon Cheeseburgers","slot":"Dinner","cuisine":"Southern","emoji":"🍔","cal":760,"p":44,"c":43,"f":45,"ingredients":[["Ground beef",6,"oz"],["Hamburger bun",1,"each"],["Bacon",2,"slice"],["Cheddar cheese",1,"oz"],["Tomato",0.5,"each"]],"steps":["Shape 6 oz ground beef into one burger patty. Slice ½ tomato.","Cook 2 slices bacon in a skillet over medium heat, turning 5–8 minutes until crisp. Remove to paper towels.","Cook the beef patty in the skillet for 4–6 minutes per side until its center reaches 160°F.","Top the patty with 1 oz cheddar during the last minute to melt; assemble on 1 hamburger bun with bacon and sliced tomato."]},{"id":"southTacoCass","name":"Taco Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":650,"p":38,"c":60,"f":29,"ingredients":[["Ground beef",5,"oz"],["Tortilla chips",1.5,"cup"],["Black beans",0.5,"cup"],["Salsa",0.5,"cup"],["Cheddar cheese",1.5,"oz"]],"steps":["Preheat oven to 375°F. Brown 5 oz ground beef in a skillet for 6–8 minutes until 160°F.","Drain and rinse ½ cup black beans. Stir the beans and ½ cup salsa into the beef.","Spread half of 1½ cups tortilla chips in a small baking dish, add beef mixture and top with remaining chips.","Scatter 1½ oz cheddar on top and bake 12–15 minutes until hot and cheese melts."]},{"id":"southTacoSoup","name":"Taco Soup","slot":"Dinner","cuisine":"Southern","emoji":"🍲","cal":540,"p":38,"c":60,"f":18,"ingredients":[["Ground beef",5,"oz"],["Black beans",0.5,"cup"],["Corn",0.5,"cup"],["Diced tomatoes",1,"cup"],["Taco seasoning",1,"tbsp"]],"steps":["Brown 5 oz ground beef in a saucepan over medium heat for 6–8 minutes until 160°F; drain fat.","Drain ½ cup black beans and ½ cup corn. Add both to the beef with 1 cup diced tomatoes.","Stir in 1 tbsp taco seasoning and ½ cup water; bring to a simmer.","Cover loosely and cook 15–20 minutes over low heat, stirring occasionally. Serve when hot and flavors combine."]},{"id":"southBakedSpaghetti","name":"Baked Spaghetti","slot":"Dinner","cuisine":"Southern","emoji":"🍝","cal":690,"p":40,"c":76,"f":26,"ingredients":[["Spaghetti",3,"oz"],["Ground beef",5,"oz"],["Tomato sauce",1,"cup"],["Mozzarella cheese",1.5,"oz"],["Parmesan",1,"tbsp"]],"steps":["Preheat oven to 375°F. Boil 3 oz dry spaghetti according to its package, then drain.","Brown 5 oz ground beef in a skillet for 6–8 minutes until 160°F; stir in 1 cup tomato sauce and simmer 3 minutes.","Combine the drained pasta and meat sauce in a small baking dish.","Top with 1½ oz mozzarella and 1 tbsp Parmesan. Bake uncovered 15–20 minutes until bubbling and melted."]},{"id":"southLasagna","name":"Homestyle Lasagna","slot":"Dinner","cuisine":"Southern","emoji":"🍝","cal":720,"p":43,"c":68,"f":31,"ingredients":[["Lasagna noodles",3,"oz"],["Ground beef",5,"oz"],["Tomato sauce",1,"cup"],["Ricotta cheese",0.5,"cup"],["Mozzarella cheese",1.5,"oz"]],"steps":["Preheat oven to 375°F. Boil 3 oz dry lasagna noodles according to the package; drain.","Brown 5 oz ground beef in a skillet until 160°F, about 6–8 minutes. Mix in 1 cup tomato sauce and simmer for 3 minutes.","In a small baking dish, alternate layers of noodles, beef sauce, ½ cup ricotta and 1½ oz mozzarella, saving some sauce and mozzarella for the top.","Cover with foil and bake 20 minutes, then uncover and bake 10–15 minutes until bubbly. Rest 10 minutes before slicing."]},{"id":"southGoulash","name":"American Goulash","slot":"Dinner","cuisine":"Southern","emoji":"🍲","cal":620,"p":37,"c":72,"f":21,"ingredients":[["Ground beef",5,"oz"],["Elbow macaroni",3,"oz"],["Diced tomatoes",1,"cup"],["Tomato sauce",0.5,"cup"],["Onion",0.25,"each"]],"steps":["Boil 3 oz dry elbow macaroni as directed on its package and drain.","Dice ¼ onion and cook with 5 oz ground beef in a skillet over medium heat for 6–8 minutes until beef reaches 160°F.","Add 1 cup diced tomatoes and ½ cup tomato sauce. Simmer 8–10 minutes.","Stir in cooked macaroni and heat 2 more minutes until steaming. Serve hot."]},{"id":"southSausagePotato","name":"Smoked Sausage and Potatoes","slot":"Dinner","cuisine":"Southern","emoji":"🌭","cal":650,"p":29,"c":54,"f":36,"ingredients":[["Smoked sausage",6,"oz"],["Potatoes",1.5,"cup"],["Bell pepper",0.5,"each"],["Onion",0.5,"each"],["Olive oil",1,"tbsp"]],"steps":["Preheat oven to 425°F. Cut 1½ cups potatoes into small cubes and slice 6 oz smoked sausage, ½ bell pepper and ½ onion.","Toss everything with 1 tbsp olive oil on a sheet pan and spread into a single layer.","Roast 25–35 minutes, stirring halfway, until potatoes are fork-tender and sausage is steaming hot.","Let cool for 2 minutes before serving."]},{"id":"southRedBeans","name":"Red Beans and Sausage","slot":"Dinner","cuisine":"Southern","emoji":"🍛","cal":610,"p":32,"c":67,"f":25,"ingredients":[["Red beans",1,"cup"],["Smoked sausage",4,"oz"],["Onion",0.25,"each"],["Celery",0.5,"cup"],["Cooked rice",0.75,"cup"]],"steps":["Dice ¼ onion and ½ cup celery; slice 4 oz smoked sausage.","Cook sausage, onion and celery in a saucepan over medium heat for 5–7 minutes until vegetables soften.","Add 1 cup cooked or canned red beans (drained) and ½ cup water. Bring to a simmer and cook 12–15 minutes, mashing a spoonful of beans to thicken.","Warm ¾ cup cooked rice until steaming. Spoon beans and sausage over the rice."]},{"id":"southJambalaya","name":"Chicken and Sausage Jambalaya","slot":"Dinner","cuisine":"Southern","emoji":"🍛","cal":640,"p":42,"c":67,"f":23,"ingredients":[["Chicken breast",4,"oz"],["Smoked sausage",3,"oz"],["Long-grain rice",0.75,"cup"],["Diced tomatoes",0.75,"cup"],["Bell pepper",0.5,"each"]],"steps":["Cut 4 oz chicken breast and 3 oz smoked sausage into small pieces; dice ½ bell pepper.","Brown chicken in a covered saucepan over medium heat for 5–7 minutes until 165°F. Add sausage and pepper, stirring 2–3 minutes.","Stir in ¾ cup uncooked long-grain rice and ¾ cup diced tomatoes, then add ¾ cup water. Bring to a low boil.","Cover and simmer over low heat 18–22 minutes until rice is tender, adding water if needed. Rest covered 5 minutes before serving."]},{"id":"southDirtyRice","name":"Dirty Rice with Sausage","slot":"Dinner","cuisine":"Southern","emoji":"🍚","cal":590,"p":30,"c":66,"f":24,"ingredients":[["Ground sausage",4,"oz"],["Cooked rice",1.25,"cup"],["Bell pepper",0.5,"each"],["Onion",0.25,"each"],["Celery",0.5,"cup"]],"steps":["Dice ½ bell pepper, ¼ onion and ½ cup celery.","Brown 4 oz ground sausage in a skillet over medium heat for 6–8 minutes, breaking it into crumbles until cooked through.","Add the diced vegetables with 2 tbsp water and cook 4–5 minutes until tender.","Stir in 1¼ cups already-cooked rice and heat for 2–3 minutes until steaming throughout."]},{"id":"southShrimpGrits","name":"Shrimp and Grits","slot":"Dinner","cuisine":"Southern","emoji":"🍤","cal":590,"p":36,"c":52,"f":26,"ingredients":[["Shrimp",6,"oz"],["Grits",0.75,"cup"],["Cheddar cheese",1,"oz"],["Butter",1,"tbsp"],["Green onion",2,"each"]],"steps":["Measure ¾ cup grits and check the package for its water ratio and cook time; quick and traditional grits cook differently. Bring the required amount of water to a boil.","Slowly whisk in ¾ cup grits and lower the heat. Stir frequently for the package's stated time until smooth and tender.","Stir 1 oz cheddar cheese and ½ tbsp of the 1 tbsp butter into the hot grits.","Peel and devein 6 oz shrimp if needed. Melt the remaining ½ tbsp butter in a skillet over medium heat.","Add the shrimp in one layer and cook 2–3 minutes per side, until opaque and firm (145°F if checked with a thermometer).","Spoon the cheesy grits into a bowl, add shrimp on top and finish with 2 sliced green onions."]},{"id":"southFriedCatfish","name":"Southern Fried Catfish","slot":"Dinner","cuisine":"Southern","emoji":"🐟","cal":620,"p":43,"c":48,"f":29,"ingredients":[["Catfish fillet",6,"oz"],["Cornmeal",0.5,"cup"],["Buttermilk",0.5,"cup"],["Cooking oil",1.5,"tbsp"],["Coleslaw",0.5,"cup"]],"steps":["Pour ½ cup buttermilk into a shallow bowl and put ½ cup cornmeal on a separate plate. Pat 6 oz catfish fillet dry.","Dip the catfish in buttermilk, then press into the cornmeal to coat both sides.","Heat 1½ tbsp cooking oil in a nonstick skillet over medium heat until shimmering. Cook fish about 3–5 minutes per side, adjusting for thickness.","Fish should flake easily and reach 145°F at its thickest point. Serve with ½ cup prepared coleslaw."]},{"id":"southBlackenedCatfish","name":"Blackened Catfish with Rice","slot":"Dinner","cuisine":"Southern","emoji":"🐟","cal":540,"p":42,"c":52,"f":17,"ingredients":[["Catfish fillet",6,"oz"],["Cajun seasoning",1,"tsp"],["Cooked rice",1,"cup"],["Green beans",1,"cup"],["Butter",1,"tsp"]],"steps":["Pat 6 oz catfish fillet dry and rub both sides evenly with 1 tsp Cajun seasoning.","Melt 1 tsp butter in a nonstick skillet over medium-high heat.","Cook fish 3–5 minutes per side until browned and opaque, reaching 145°F at the thickest part.","Warm 1 cup cooked rice until steaming; steam 1 cup green beans for 4–6 minutes until tender. Serve fish with rice and beans."]},{"id":"southPulledPork","name":"BBQ Pulled Pork Plate","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":690,"p":43,"c":65,"f":27,"ingredients":[["Pork shoulder",6,"oz"],["BBQ sauce",0.25,"cup"],["Baked beans",0.75,"cup"],["Coleslaw",0.5,"cup"],["Cornbread",1,"each"]],"steps":["Preheat oven to 300°F. Put 6 oz pork shoulder in a small covered baking dish with ¼ cup water.","Cover tightly and cook for 2½–3½ hours, until the meat pulls apart easily with two forks. Check periodically that the pan has moisture.","Shred cooked pork and mix with ¼ cup BBQ sauce. Heat it together for 2–3 minutes.","Warm ¾ cup baked beans and 1 piece prepared cornbread until hot. Serve with ½ cup prepared coleslaw."]},{"id":"southPorkChops","name":"Oven-Baked Pork Chops","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":570,"p":45,"c":44,"f":22,"ingredients":[["Pork chop",6,"oz"],["Potatoes",1,"cup"],["Green beans",1,"cup"],["Olive oil",1,"tbsp"]],"steps":["Preheat oven to 400°F. Cube 1 cup potatoes and toss with ½ tbsp of the 1 tbsp olive oil.","Roast potatoes on a sheet pan for 15 minutes. Pat 6 oz pork chop dry and rub with remaining ½ tbsp olive oil.","Add the pork chop to the pan and roast for another 12–20 minutes, depending on thickness, until the center reaches 145°F.","Rest pork for 3 minutes. Steam 1 cup green beans 4–6 minutes until tender, and serve with potatoes."]},{"id":"southBeansCornbread","name":"Pinto Beans and Cornbread","slot":"Dinner","cuisine":"Southern","emoji":"🫘","cal":560,"p":24,"c":88,"f":13,"ingredients":[["Pinto beans",1.5,"cup"],["Cornbread",1,"each"],["Onion",0.25,"each"],["Ham",2,"oz"]],"steps":["Use 1½ cups cooked or canned pinto beans, drained if canned. Finely chop ¼ onion and dice 2 oz ham.","In a saucepan, cook onion and ham with 2 tbsp water for 3–4 minutes until onion softens.","Add 1½ cups beans and ½ cup water; simmer 10–15 minutes, stirring occasionally until hot and slightly thickened.","Heat 1 piece prepared cornbread according to its package or recipe and serve with the beans."]},{"id":"lunchChickenSalad","name":"Southern Chicken Salad Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":490,"p":34,"c":39,"f":22,"ingredients":[["Cooked chicken",4,"oz"],["Mayonnaise",1.5,"tbsp"],["Celery",0.25,"cup"],["Sandwich bread",2,"slice"],["Pickles",2,"tbsp"]],"steps":["Measure 4 oz fully cooked chicken and chop or shred it into small pieces. Finely dice ¼ cup celery and chop 2 tbsp pickles.","In a bowl, combine the chicken, celery and pickles with 1½ tbsp mayonnaise.","Stir until the mixture is evenly coated. Keep chilled until ready to serve.","Spoon the chicken salad evenly between 2 slices sandwich bread. Serve immediately or refrigerate the filling."]},{"id":"lunchChickenCroissant","name":"Chicken Salad Croissant","slot":"Lunch","cuisine":"Southern","emoji":"🥐","cal":560,"p":32,"c":45,"f":28,"ingredients":[["Cooked chicken",4,"oz"],["Mayonnaise",1.5,"tbsp"],["Celery",0.25,"cup"],["Croissant",1,"each"],["Grapes",0.25,"cup"]],"steps":["Finely chop 4 oz fully cooked chicken and ¼ cup celery; halve or quarter ¼ cup grapes.","Stir chicken, celery and grapes with 1½ tbsp mayonnaise until coated.","Split 1 croissant horizontally without cutting all the way through.","Spoon the chicken salad into the croissant. Serve immediately or refrigerate until ready."]},{"id":"lunchPimento","name":"Pimento Cheese Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":510,"p":20,"c":36,"f":32,"ingredients":[["Cheddar cheese",2,"oz"],["Pimentos",2,"tbsp"],["Mayonnaise",1,"tbsp"],["Sandwich bread",2,"slice"]],"steps":["Shred 2 oz cheddar cheese. Drain and finely chop 2 tbsp pimentos.","Mix shredded cheddar, pimentos and 1 tbsp mayonnaise until creamy.","Spread the mixture evenly on 1 slice of sandwich bread and cover with the second slice.","Cut in half and serve chilled or at room temperature."]},{"id":"lunchPimentoBacon","name":"Pimento Cheese and Bacon Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":620,"p":25,"c":37,"f":41,"ingredients":[["Cheddar cheese",2,"oz"],["Pimentos",2,"tbsp"],["Mayonnaise",1,"tbsp"],["Bacon",2,"slice"],["Sandwich bread",2,"slice"]],"steps":["Cook 2 slices bacon in a skillet over medium heat for 5–8 minutes until crisp; drain.","Mix 2 oz shredded cheddar, 2 tbsp drained pimentos and 1 tbsp mayonnaise in a bowl.","Spread the pimento cheese onto 1 slice of sandwich bread. Break the cooked bacon over the filling.","Top with the second slice of sandwich bread and serve."]},{"id":"lunchHamBiscuit","name":"Country Ham Biscuit","slot":"Lunch","cuisine":"Southern","emoji":"🥯","cal":430,"p":24,"c":39,"f":20,"ingredients":[["Country ham",3,"oz"],["Biscuit",1,"each"],["Cheddar cheese",1,"oz"],["Mustard",1,"tsp"]],"steps":["Warm 1 prepared biscuit according to its package until heated through; split in half.","Heat 3 oz country ham in a nonstick skillet over medium-low heat for 1–2 minutes per side until hot.","Spread 1 tsp mustard on the biscuit, add the hot ham and 1 oz cheddar.","Close the biscuit and heat briefly until the cheese softens."]},{"id":"lunchHotHam","name":"Hot Ham and Cheese","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":500,"p":31,"c":39,"f":24,"ingredients":[["Ham",4,"oz"],["Cheddar cheese",1,"oz"],["Sandwich bread",2,"slice"],["Butter",1,"tsp"]],"steps":["Lay out 2 slices sandwich bread. Place 4 oz ham and 1 oz cheddar between them.","Spread 1 tsp butter over the outside faces of the bread.","Heat a skillet over medium-low heat. Cook the sandwich 2–3 minutes per side until golden, the ham is steaming and the cheese melts.","Let rest 1 minute, then slice and serve."]},{"id":"lunchBLT","name":"Classic BLT","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":470,"p":20,"c":38,"f":27,"ingredients":[["Bacon",4,"slice"],["Sandwich bread",2,"slice"],["Tomato",0.5,"each"],["Lettuce",1,"cup"],["Mayonnaise",1,"tbsp"]],"steps":["Cook 4 slices bacon in a skillet over medium heat for 6–9 minutes, turning until crisp; drain on paper towels.","Toast 2 slices sandwich bread until golden.","Slice ½ tomato and wash and dry 1 cup lettuce.","Spread 1 tbsp mayonnaise on one toast slice, then layer lettuce, tomato and crisp bacon. Top with remaining bread."]},{"id":"lunchBologna","name":"Fried Bologna Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":500,"p":22,"c":39,"f":29,"ingredients":[["Bologna",3,"oz"],["Sandwich bread",2,"slice"],["Cheddar cheese",1,"oz"],["Mustard",1,"tbsp"]],"steps":["Heat a nonstick skillet over medium heat. Cook 3 oz bologna for 1–2 minutes per side until lightly browned.","Put 1 oz cheddar on the bologna, cover skillet for about 30 seconds to melt.","Spread 1 tbsp mustard across 2 slices sandwich bread.","Place the hot cheesy bologna between the bread slices and serve."]},{"id":"lunchPattyMelt","name":"Patty Melt","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":650,"p":38,"c":42,"f":37,"ingredients":[["Ground beef",5,"oz"],["Rye bread",2,"slice"],["Swiss cheese",1,"oz"],["Onion",0.5,"each"],["Butter",1,"tsp"]],"steps":["Thinly slice ½ onion. Melt ½ tsp of the 1 tsp butter in a skillet and cook onion over medium-low heat 10–12 minutes until soft and golden.","Shape 5 oz ground beef into a thin patty. Cook in a separate skillet over medium heat about 4–5 minutes per side until 160°F.","Place beef, cooked onion and 1 oz Swiss cheese between 2 slices rye bread.","Melt remaining ½ tsp butter in the skillet and toast the sandwich 2–3 minutes per side until the bread browns and cheese melts."]},{"id":"lunchGrilledCheeseSoup","name":"Grilled Cheese and Tomato Soup","slot":"Lunch","cuisine":"Southern","emoji":"🥣","cal":560,"p":21,"c":59,"f":28,"ingredients":[["Sandwich bread",2,"slice"],["Cheddar cheese",2,"oz"],["Butter",1,"tsp"],["Tomato soup",1.5,"cup"]],"steps":["Place 2 oz cheddar cheese between 2 slices sandwich bread. Spread 1 tsp butter over the outer faces.","Cook in a skillet over medium-low heat for 2–3 minutes per side until both sides are golden and cheese melts.","Pour 1½ cups ready-to-heat tomato soup into a saucepan and warm according to package directions until steaming, stirring frequently.","Slice the sandwich and serve alongside the hot soup."]},{"id":"lunchPulledPork","name":"Pulled Pork Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":590,"p":36,"c":58,"f":23,"ingredients":[["Pulled pork",5,"oz"],["BBQ sauce",2,"tbsp"],["Hamburger bun",1,"each"],["Coleslaw",0.5,"cup"]],"steps":["Measure 5 oz fully cooked pulled pork and mix with 2 tbsp BBQ sauce in a saucepan.","Warm over medium-low heat for 4–5 minutes, stirring until steaming hot throughout.","Split and lightly toast 1 hamburger bun for 30–60 seconds.","Pile warm pork onto the bun and top with ½ cup prepared coleslaw before closing."]},{"id":"lunchBbqChicken","name":"BBQ Chicken Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":510,"p":41,"c":50,"f":15,"ingredients":[["Chicken breast",5,"oz"],["BBQ sauce",2,"tbsp"],["Hamburger bun",1,"each"],["Pickles",0.25,"cup"]],"steps":["Cook 5 oz chicken breast in a nonstick skillet over medium heat for about 5–7 minutes per side until center reaches 165°F.","Rest 3 minutes, then shred or slice chicken and toss with 2 tbsp BBQ sauce.","Split and toast 1 hamburger bun cut-side down for 30–60 seconds.","Fill the bun with BBQ chicken and ¼ cup sliced pickles."]},{"id":"lunchFriedChickenSand","name":"Fried Chicken Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":620,"p":39,"c":54,"f":27,"ingredients":[["Chicken breast",5,"oz"],["All-purpose flour",0.5,"cup"],["Buttermilk",0.5,"cup"],["Hamburger bun",1,"each"],["Pickles",0.25,"cup"]],"steps":["Dip 5 oz chicken breast into ½ cup buttermilk, then press it into ½ cup flour to coat.","Heat a nonstick skillet over medium with enough pan heat for shallow frying. Cook chicken about 5–7 minutes per side until the coating browns and the center reaches 165°F. Use a lightly oiled nonstick pan if available; oil is not included in this recipe's measured ingredients.","Rest chicken 3 minutes on a rack or paper towel. Toast 1 hamburger bun if desired.","Put chicken on the bun with ¼ cup sliced pickles and serve."]},{"id":"lunchTenderWrap","name":"Chicken Tender Wrap","slot":"Lunch","cuisine":"Southern","emoji":"🌯","cal":540,"p":37,"c":49,"f":22,"ingredients":[["Chicken tenders",4,"oz"],["Flour tortilla",1,"each"],["Lettuce",1,"cup"],["Tomato",0.5,"each"],["Ranch dressing",1.5,"tbsp"]],"steps":["Cook 4 oz chicken tenders in a nonstick skillet over medium heat for about 5–7 minutes per side until they reach 165°F.","Wash and chop 1 cup lettuce and dice ½ tomato. Slice the cooked chicken into thin strips.","Warm 1 flour tortilla briefly until flexible. Spread with 1½ tbsp ranch dressing.","Layer lettuce, tomato and warm chicken along the center, fold the sides and roll tightly."]},{"id":"lunchBaconRanchWrap","name":"Chicken Bacon Ranch Wrap","slot":"Lunch","cuisine":"Southern","emoji":"🌯","cal":610,"p":41,"c":46,"f":28,"ingredients":[["Chicken breast",4,"oz"],["Bacon",2,"slice"],["Flour tortilla",1,"each"],["Lettuce",1,"cup"],["Ranch dressing",1.5,"tbsp"]],"steps":["Cook 2 slices bacon in a skillet over medium heat until crisp, about 6–8 minutes; drain.","Cook 4 oz chicken breast in a nonstick skillet about 5–7 minutes per side until 165°F; rest and slice.","Warm 1 flour tortilla, spread with 1½ tbsp ranch dressing and add 1 cup chopped lettuce.","Arrange chicken and crumbled bacon across the center, then fold sides inward and roll into a wrap."]},{"id":"lunchMeatloafSand","name":"Meatloaf Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":570,"p":34,"c":48,"f":27,"ingredients":[["Cooked meatloaf",5,"oz"],["Sandwich bread",2,"slice"],["Ketchup",1,"tbsp"],["Pickles",0.25,"cup"]],"steps":["Slice 5 oz fully cooked meatloaf into thick pieces.","Heat the meatloaf in a covered skillet over medium-low heat with 1 tbsp water for 3–5 minutes until steaming.","Spread 1 tbsp ketchup on 1 of 2 slices sandwich bread.","Layer hot meatloaf and ¼ cup pickles onto the bread, then close with second slice."]},{"id":"lunchCfsSand","name":"Chicken Fried Steak Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":650,"p":38,"c":58,"f":29,"ingredients":[["Cube steak",5,"oz"],["All-purpose flour",0.5,"cup"],["Hamburger bun",1,"each"],["Lettuce",1,"cup"],["Tomato",0.5,"each"]],"steps":["Pat 5 oz cube steak dry and press both sides into ½ cup flour, discarding flour contaminated by raw meat.","Cook the coated steak in a nonstick skillet over medium heat for 4–5 minutes per side until browned and at least 145°F; rest 3 minutes.","Slice ½ tomato and prepare 1 cup washed lettuce; split 1 hamburger bun.","Set the cooked steak on the bun, top with lettuce and tomato and close the sandwich."]},{"id":"lunchCatfishSand","name":"Fried Catfish Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":570,"p":36,"c":52,"f":24,"ingredients":[["Catfish fillet",5,"oz"],["Cornmeal",0.4,"cup"],["Hamburger bun",1,"each"],["Coleslaw",0.5,"cup"]],"steps":["Pat 5 oz catfish fillet dry, then press both sides into ⅖ cup cornmeal, coating evenly.","Heat a nonstick skillet over medium heat. Cook the coated catfish for about 4–5 minutes on each side until golden and the center reaches 145°F. Use a lightly oiled nonstick skillet if needed; added oil is not included in the listed ingredients.","Split 1 hamburger bun and toast the cut faces for about 30 seconds.","Place cooked fish on the bun, top with ½ cup prepared coleslaw and close the sandwich."]},{"id":"lunchLoadedPotato","name":"BBQ Pork Loaded Baked Potato","slot":"Lunch","cuisine":"Southern","emoji":"🥔","cal":610,"p":35,"c":66,"f":23,"ingredients":[["Baked potato",1,"each"],["Pulled pork",4,"oz"],["BBQ sauce",2,"tbsp"],["Cheddar cheese",1,"oz"],["Green onion",1,"each"]],"steps":["Heat 1 already-baked potato until hot throughout, or bake a raw potato at 425°F for 45–60 minutes until fork-tender.","Combine 4 oz fully cooked pulled pork and 2 tbsp BBQ sauce in a saucepan. Heat over medium-low for 4–5 minutes until steaming.","Shred 1 oz cheddar cheese and slice 1 green onion.","Split the hot potato, fluff the inside with a fork, pile on the hot BBQ pork and cheddar and finish with sliced green onion."]},{"id":"lunchPotatoSoup","name":"Loaded Potato Soup","slot":"Lunch","cuisine":"Southern","emoji":"🥣","cal":520,"p":22,"c":55,"f":24,"ingredients":[["Potatoes",1.5,"cup"],["Chicken broth",1.5,"cup"],["Milk",0.5,"cup"],["Cheddar cheese",1,"oz"],["Bacon",2,"slice"]],"steps":["Peel and dice 1½ cups potatoes into ½-inch pieces. Put in a saucepan with 1½ cups chicken broth.","Bring to a low boil, cover and simmer 12–18 minutes until potatoes mash easily.","Meanwhile cook 2 bacon slices in a skillet over medium heat 6–8 minutes until crisp; crumble.","Lightly mash half the potatoes in their broth. Stir in ½ cup milk and gently heat 2–3 minutes without boiling hard.","Ladle soup into a bowl; top with 1 oz shredded cheddar and the 2 slices crumbled bacon."]}]);recipes.push(...[{"id":"southPorkGravy","name":"Pork Chops and Gravy","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":620,"p":44,"c":38,"f":31,"ingredients":[["Pork chop",6,"oz"],["Onion",0.5,"each"],["Chicken broth",0.75,"cup"],["All-purpose flour",1.5,"tbsp"],["Mashed potatoes",1,"cup"]],"steps":["Slice ½ onion and pat 6 oz pork chop dry. Dust chop with ½ tbsp of the 1½ tbsp flour; keep remaining clean flour aside.","Brown pork in a nonstick skillet over medium heat about 3 minutes per side; remove.","Cook onion with 2 tbsp water in skillet for 4–5 minutes. Stir in reserved 1 tbsp flour for 1 minute, then slowly whisk in ¾ cup chicken broth.","Return chop, cover and gently simmer about 6–10 minutes until it reaches 145°F; rest pork 3 minutes.","Warm 1 cup prepared mashed potatoes; top with pork, onions and gravy."]},{"id":"southFriedPork","name":"Fried Pork Chops","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":650,"p":44,"c":36,"f":36,"ingredients":[["Pork chop",6,"oz"],["All-purpose flour",0.5,"cup"],["Egg",1,"each"],["Milk",0.25,"cup"],["Cooking oil",1.5,"tbsp"]],"steps":["Pat 6 oz pork chop dry. Beat 1 egg with ¼ cup milk in a shallow bowl; put ½ cup flour on a plate.","Dip the pork chop in flour, then egg mixture, then flour again. Discard any raw-meat-contact flour.","Heat 1½ tbsp cooking oil in a skillet over medium heat until shimmering. Cook the coated chop about 4–6 minutes per side until golden; lower heat if crust browns too fast.","Confirm the thickest part reaches 145°F and let rest 3 minutes before serving."]},{"id":"southPorkTenderloin","name":"Pork Tenderloin with Roasted Potatoes","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":570,"p":47,"c":45,"f":20,"ingredients":[["Pork tenderloin",6,"oz"],["Potatoes",1.25,"cup"],["Green beans",1,"cup"],["Olive oil",1,"tbsp"]],"steps":["Preheat oven to 425°F. Cut 1¼ cups potatoes into ¾-inch cubes and toss with ½ tbsp olive oil.","Spread potatoes on a sheet pan and roast 12 minutes.","Rub 6 oz pork tenderloin with remaining ½ tbsp olive oil. Add it to pan and roast 15–22 minutes depending on thickness, turning potatoes halfway.","Check pork center reaches 145°F; let rest at least 3 minutes. Meanwhile steam 1 cup green beans 4–6 minutes until tender.","Slice tenderloin and serve with roasted potatoes and green beans."]},{"id":"southCountryRibs","name":"Country-Style Pork Ribs","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":710,"p":46,"c":48,"f":37,"ingredients":[["Country-style pork ribs",7,"oz"],["BBQ sauce",0.25,"cup"],["Baked beans",0.75,"cup"],["Coleslaw",0.5,"cup"]],"steps":["Preheat oven to 300°F. Place 7 oz country-style pork ribs in a small covered baking dish with 2 tbsp water.","Cover tightly and bake 2–2½ hours until ribs are fork-tender, checking that pan does not dry out.","Brush ribs with ¼ cup BBQ sauce and bake uncovered for 10–15 minutes at 400°F until sauce sets.","Warm ¾ cup prepared baked beans until steaming. Serve ribs with beans and ½ cup prepared coleslaw."]},{"id":"southBbqRibs","name":"Oven-Baked BBQ Ribs","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":730,"p":45,"c":52,"f":39,"ingredients":[["Pork ribs",7,"oz"],["BBQ sauce",0.25,"cup"],["Cornbread",1,"each"],["Coleslaw",0.5,"cup"]],"steps":["Preheat oven to 300°F. Put 7 oz pork ribs in a small baking dish and add 2 tbsp water.","Cover snugly with foil and bake about 2–2½ hours until tender; check that the pan still has moisture.","Uncover and brush ribs with ¼ cup BBQ sauce; increase oven to 400°F and roast 10–15 minutes until glazed.","Warm 1 piece prepared cornbread and serve with ½ cup prepared coleslaw."]},{"id":"southHamMac","name":"Baked Ham with Mac and Cheese","slot":"Dinner","cuisine":"Southern","emoji":"🍖","cal":690,"p":38,"c":58,"f":34,"ingredients":[["Ham",5,"oz"],["Macaroni",2.5,"oz"],["Cheddar cheese",2,"oz"],["Milk",0.5,"cup"],["Green beans",1,"cup"]],"steps":["Boil 2½ oz dry macaroni in water according to package, usually 7–10 minutes; drain.","Heat ½ cup milk in saucepan over low heat. Add 2 oz shredded cheddar gradually and stir until just melted; avoid vigorous boiling.","Stir the drained macaroni into the cheese sauce; heat 1–2 minutes until creamy.","Warm 5 oz fully cooked ham in a skillet or oven until steaming. Steam 1 cup green beans 4–6 minutes; serve all together."]},{"id":"southHamPotato","name":"Ham and Potato Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":620,"p":32,"c":57,"f":29,"ingredients":[["Ham",4,"oz"],["Potatoes",1.5,"cup"],["Cheddar cheese",1.5,"oz"],["Milk",0.5,"cup"],["Onion",0.25,"each"]],"steps":["Preheat oven to 375°F. Thinly slice 1½ cups potatoes and finely dice ¼ onion; dice 4 oz cooked ham.","Place potatoes, onion and ham in a small covered baking dish. Pour in ½ cup milk.","Cover with foil and bake 40–50 minutes until potatoes are fork-tender.","Sprinkle 1½ oz shredded cheddar over top; bake uncovered 5–8 minutes until melted. Let stand 5 minutes before serving."]},{"id":"southBlackEyed","name":"Black-Eyed Peas with Ham and Cornbread","slot":"Dinner","cuisine":"Southern","emoji":"🫘","cal":580,"p":31,"c":79,"f":17,"ingredients":[["Black-eyed peas",1.25,"cup"],["Ham",3,"oz"],["Onion",0.25,"each"],["Cornbread",1,"each"]],"steps":["Use 1¼ cups cooked or canned black-eyed peas, rinsed if canned; dice 3 oz cooked ham and ¼ onion.","Put ham and onion in a saucepan with 2 tbsp water; cook over medium heat 3–4 minutes until onion softens.","Add the black-eyed peas and ½ cup water. Simmer uncovered 12–15 minutes, stirring occasionally until thickened and hot.","Warm 1 piece prepared cornbread and serve alongside the peas."]},{"id":"southBeansRice","name":"Southern Beans and Rice","slot":"Dinner","cuisine":"Southern","emoji":"🍛","cal":540,"p":24,"c":88,"f":10,"ingredients":[["Pinto beans",1,"cup"],["Cooked rice",1,"cup"],["Onion",0.25,"each"],["Smoked sausage",2,"oz"]],"steps":["Finely dice ¼ onion and slice 2 oz smoked sausage.","Cook the sausage and onion in a saucepan over medium heat for 4–5 minutes until onion softens.","Add 1 cup cooked or canned pinto beans and ¼ cup water. Simmer 10–12 minutes, mashing a few beans to thicken.","Warm 1 cup already-cooked rice until steaming. Spoon the beans and sausage over rice."]},{"id":"southVegPlate","name":"Southern Vegetable Plate with Cornbread","slot":"Dinner","cuisine":"Southern","emoji":"🥬","cal":520,"p":20,"c":78,"f":17,"ingredients":[["Collard greens",1,"cup"],["Black-eyed peas",0.75,"cup"],["Corn",0.75,"cup"],["Cornbread",1,"each"]],"steps":["Use 1 cup washed collard greens, ¾ cup cooked or canned black-eyed peas and ¾ cup corn kernels.","Place collard greens with ¼ cup water in a covered saucepan over medium-low heat; simmer 15–25 minutes until tender, adding water as necessary.","Heat black-eyed peas in a small saucepan with 2 tbsp water for 5 minutes; heat corn in another pan for 3–5 minutes until steaming.","Warm 1 prepared piece of cornbread. Arrange greens, peas and corn on a plate and serve with cornbread."]},{"id":"southSausageMac","name":"Mac and Cheese with Smoked Sausage","slot":"Dinner","cuisine":"Southern","emoji":"🧀","cal":690,"p":32,"c":62,"f":35,"ingredients":[["Smoked sausage",4,"oz"],["Macaroni",2.5,"oz"],["Cheddar cheese",2,"oz"],["Milk",0.5,"cup"]],"steps":["Boil 2½ oz dry macaroni per package instructions, usually 7–10 minutes; drain.","Slice 4 oz smoked sausage and brown in a skillet over medium heat 4–6 minutes, turning until hot.","Warm ½ cup milk on low heat and gradually stir in 2 oz shredded cheddar until melted.","Fold cooked macaroni and browned sausage into cheese sauce and heat 1–2 minutes until evenly coated."]},{"id":"southBbqPotato","name":"Loaded Baked Potato with BBQ Beef","slot":"Dinner","cuisine":"Southern","emoji":"🥔","cal":650,"p":39,"c":66,"f":25,"ingredients":[["Baked potato",1,"each"],["Shredded beef",5,"oz"],["BBQ sauce",2,"tbsp"],["Cheddar cheese",1,"oz"],["Green onion",1,"each"]],"steps":["Heat 1 already-baked potato until hot throughout; if starting raw, bake a scrubbed potato at 425°F about 45–60 minutes until fork-tender.","Warm 5 oz fully cooked shredded beef with 2 tbsp BBQ sauce in saucepan over medium-low heat 4–5 minutes, stirring.","Split hot potato and fluff center with a fork. Spoon BBQ beef into center.","Top with 1 oz shredded cheddar and 1 sliced green onion; allow cheese to melt before serving."]},{"id":"southChiliCornbread","name":"Homestyle Chili with Cornbread","slot":"Dinner","cuisine":"Southern","emoji":"🍲","cal":640,"p":38,"c":75,"f":23,"ingredients":[["Ground beef",5,"oz"],["Kidney beans",0.75,"cup"],["Diced tomatoes",1,"cup"],["Chili seasoning",1,"tbsp"],["Cornbread",1,"each"]],"steps":["Brown 5 oz ground beef in a saucepan over medium heat for 6–8 minutes until 160°F; drain extra fat.","Drain and rinse ¾ cup kidney beans. Add them to beef with 1 cup diced tomatoes and 1 tbsp chili seasoning.","Add ¼ cup water if needed. Simmer partly covered 15–20 minutes, stirring occasionally until chili thickens.","Warm 1 prepared piece of cornbread and serve with the chili."]},{"id":"southRoastChicken","name":"Southern Sunday Roast Chicken","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":610,"p":48,"c":48,"f":25,"ingredients":[["Chicken thigh",8,"oz"],["Potatoes",1,"cup"],["Carrots",1,"cup"],["Onion",0.5,"each"],["Butter",1,"tsp"]],"steps":["Preheat the oven to 425°F. Cut 1 cup potatoes, 1 cup carrots and ½ onion into similar bite-sized pieces.","Put the vegetables in a small roasting dish. Melt 1 tsp butter and toss it with the vegetables.","Place 8 oz chicken thigh on top of the vegetables, skin side up if skin-on.","Roast uncovered for 30–40 minutes, turning the vegetables once. Chicken must reach 165°F in the thickest part and vegetables should be fork-tender.","Let the chicken rest 3–5 minutes, then serve with the roasted vegetables."]},{"id":"southChickenBiscuit","name":"Chicken Biscuit Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":640,"p":39,"c":58,"f":28,"ingredients":[["Chicken breast",5,"oz"],["Mixed vegetables",1,"cup"],["Cream of chicken soup",0.5,"cup"],["Biscuit dough",4,"oz"]],"steps":["Preheat oven to 400°F. Chop 5 oz chicken breast into small pieces.","Cook chicken in a skillet over medium heat about 7–9 minutes, stirring until 165°F.","Combine cooked chicken, 1 cup mixed vegetables and ½ cup cream of chicken soup in a small baking dish.","Cut 4 oz biscuit dough into 3–4 pieces and arrange on top, leaving space to rise.","Bake 18–25 minutes, until biscuit tops are golden and their centers are cooked, not sticky. Rest 4 minutes before serving."]},{"id":"southBaconRanchBake","name":"Bacon Ranch Chicken Bake","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":660,"p":49,"c":24,"f":40,"ingredients":[["Chicken breast",6,"oz"],["Bacon",2,"slice"],["Ranch seasoning",1,"tbsp"],["Cheddar cheese",1.5,"oz"],["Green beans",1,"cup"]],"steps":["Preheat oven to 400°F. Place 6 oz chicken breast in a small baking dish and rub with 1 tbsp ranch seasoning.","Cook 2 slices bacon in a skillet over medium heat 6–8 minutes until crisp; drain and crumble.","Bake chicken 18–25 minutes depending on thickness until center reaches 165°F.","Sprinkle chicken with 1½ oz shredded cheddar and crumbled bacon, then return to oven 2–3 minutes to melt.","Steam 1 cup green beans 4–6 minutes until tender; serve with chicken."]},{"id":"southCajunChickenPasta","name":"Cajun Chicken Pasta","slot":"Dinner","cuisine":"Southern","emoji":"🍝","cal":680,"p":46,"c":64,"f":27,"ingredients":[["Chicken breast",5,"oz"],["Pasta",3,"oz"],["Heavy cream",0.25,"cup"],["Parmesan",1,"oz"],["Cajun seasoning",1,"tsp"]],"steps":["Boil 3 oz dry pasta according to package directions, usually 8–12 minutes; drain.","Cut 5 oz chicken breast into strips and coat evenly with 1 tsp Cajun seasoning.","Cook chicken in nonstick skillet over medium heat 6–9 minutes, turning until 165°F.","Reduce heat to low; pour in ¼ cup heavy cream and simmer gently 2 minutes. Stir in 1 oz Parmesan until creamy.","Fold drained pasta into sauce and toss until hot and coated."]},{"id":"southChickenBaconPasta","name":"Chicken Bacon Ranch Pasta","slot":"Dinner","cuisine":"Southern","emoji":"🍝","cal":720,"p":47,"c":63,"f":33,"ingredients":[["Chicken breast",5,"oz"],["Pasta",3,"oz"],["Bacon",2,"slice"],["Ranch seasoning",1,"tbsp"],["Cheddar cheese",1,"oz"]],"steps":["Cook 3 oz dry pasta in boiling water according to package directions and drain, reserving 2 tbsp pasta water.","Cook 2 bacon slices in skillet over medium heat until crisp, about 6–8 minutes; transfer and crumble.","Dice 5 oz chicken breast and cook in skillet 6–9 minutes until center reaches 165°F.","Add cooked pasta, 1 tbsp ranch seasoning and reserved pasta water. Toss for 1 minute over low heat.","Stir in 1 oz cheddar and crumbled bacon until cheese melts; serve hot."]},{"id":"southCreamyGarlicChicken","name":"Creamy Garlic Chicken","slot":"Dinner","cuisine":"Southern","emoji":"🍗","cal":600,"p":47,"c":28,"f":33,"ingredients":[["Chicken breast",6,"oz"],["Garlic",2,"clove"],["Chicken broth",0.5,"cup"],["Heavy cream",0.25,"cup"],["Green beans",1,"cup"]],"steps":["Mince 2 garlic cloves and trim 1 cup green beans. Pound 6 oz chicken breast to even thickness.","Sear chicken in a nonstick skillet over medium heat for 4–5 minutes per side until browned.","Add minced garlic and cook 30 seconds, then pour in ½ cup chicken broth. Cover and simmer 4–7 minutes until chicken reaches 165°F.","Lower heat; add ¼ cup heavy cream and simmer 2–3 minutes until sauce slightly thickens.","Steam green beans 4–6 minutes; serve chicken and cream sauce alongside."]},{"id":"southChickenTacos","name":"Homestyle Chicken Tacos","slot":"Dinner","cuisine":"Southern","emoji":"🌮","cal":560,"p":40,"c":53,"f":21,"ingredients":[["Chicken breast",5,"oz"],["Flour tortillas",3,"each"],["Cheddar cheese",1,"oz"],["Lettuce",1,"cup"],["Salsa",0.25,"cup"]],"steps":["Cut 5 oz chicken breast into thin strips. Cook in a nonstick skillet over medium heat for 6–9 minutes until 165°F.","Shred 1 cup lettuce and 1 oz cheddar. Warm 3 flour tortillas in a dry skillet 15–20 seconds per side.","Divide chicken evenly between tortillas; add lettuce and shredded cheddar.","Top tacos with a total of ¼ cup salsa before serving."]},{"id":"southChickenBurritoBowl","name":"Chicken Burrito Bowl","slot":"Dinner","cuisine":"Southern","emoji":"🥙","cal":620,"p":44,"c":72,"f":18,"ingredients":[["Chicken breast",5,"oz"],["Cooked rice",1,"cup"],["Black beans",0.5,"cup"],["Corn",0.5,"cup"],["Salsa",0.25,"cup"]],"steps":["Dice 5 oz chicken breast; cook in a nonstick skillet over medium heat 6–9 minutes until 165°F.","Drain and rinse ½ cup black beans and ½ cup corn; heat both in a saucepan with 2 tbsp water for 3–4 minutes.","Warm 1 cup already-cooked rice until steaming.","Put rice in a bowl, layer over chicken, beans and corn; top with ¼ cup salsa."]},{"id":"southTeriyakiChicken","name":"Teriyaki Chicken and Rice","slot":"Dinner","cuisine":"Southern","emoji":"🍚","cal":610,"p":43,"c":78,"f":14,"ingredients":[["Chicken breast",6,"oz"],["Cooked rice",1,"cup"],["Teriyaki sauce",2,"tbsp"],["Broccoli",1,"cup"]],"steps":["Cut 6 oz chicken breast into even chunks and chop 1 cup broccoli.","Cook chicken in a nonstick skillet over medium heat 6–9 minutes until it reaches 165°F.","Add broccoli and 2 tbsp water; cover and steam for 3–4 minutes.","Add 2 tbsp teriyaki sauce from a clean container and stir for 1 minute until coated and hot.","Warm 1 cup cooked rice until steaming and serve chicken and broccoli over it."]},{"id":"southOrangeChicken","name":"Homestyle Orange Chicken","slot":"Dinner","cuisine":"Southern","emoji":"🍊","cal":650,"p":41,"c":81,"f":18,"ingredients":[["Chicken breast",6,"oz"],["Cooked rice",1,"cup"],["Orange marmalade",2,"tbsp"],["Soy sauce",1,"tbsp"],["Broccoli",1,"cup"]],"steps":["Cut 6 oz chicken breast into bite-size pieces and chop 1 cup broccoli.","Cook chicken in a nonstick skillet over medium heat for 6–9 minutes, stirring until center reaches 165°F.","Steam broccoli in skillet with 2 tbsp water and a lid for 3–4 minutes.","Stir in 2 tbsp orange marmalade and 1 tbsp soy sauce; toss over medium-low heat 1–2 minutes until glazed.","Warm 1 cup cooked rice until steaming and spoon chicken and broccoli on top."]},{"id":"southBeefStroganoff","name":"Country Beef Stroganoff","slot":"Dinner","cuisine":"Southern","emoji":"🍝","cal":650,"p":42,"c":58,"f":29,"ingredients":[["Beef strips",6,"oz"],["Egg noodles",3,"oz"],["Mushrooms",1,"cup"],["Sour cream",0.25,"cup"],["Beef broth",0.75,"cup"]],"steps":["Boil 3 oz dry egg noodles per package, typically 6–9 minutes; drain.","Slice 6 oz beef strips thinly and chop 1 cup mushrooms. Sear beef in a hot nonstick skillet over medium-high heat 2–3 minutes per side; transfer to plate.","Add mushrooms with 2 tbsp water; cook 4–5 minutes. Pour in ¾ cup beef broth and simmer 4 minutes.","Return beef and heat until cooked through, then remove pan from heat. Stir in ¼ cup sour cream until creamy; avoid boiling.","Spoon beef and mushroom sauce over the noodles."]},{"id":"southCheeseburgerCass","name":"Cheeseburger Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":700,"p":39,"c":67,"f":31,"ingredients":[["Ground beef",5,"oz"],["Elbow macaroni",3,"oz"],["Cheddar cheese",1.5,"oz"],["Tomato sauce",0.5,"cup"],["Onion",0.25,"each"]],"steps":["Preheat oven to 375°F. Boil 3 oz dry elbow macaroni according to package; drain.","Dice ¼ onion and brown with 5 oz ground beef in skillet 6–8 minutes until beef reaches 160°F.","Stir ½ cup tomato sauce into beef and fold in cooked macaroni. Transfer to small baking dish.","Top with 1½ oz cheddar and bake uncovered 12–18 minutes until bubbling and cheese melts."]},{"id":"southChiliBurger","name":"Chili Cheeseburgers","slot":"Dinner","cuisine":"Southern","emoji":"🍔","cal":760,"p":43,"c":57,"f":41,"ingredients":[["Ground beef",6,"oz"],["Hamburger bun",1,"each"],["Chili",0.5,"cup"],["Cheddar cheese",1,"oz"]],"steps":["Shape 6 oz ground beef into one patty. Cook in nonstick skillet over medium heat 4–6 minutes per side, until 160°F.","Heat ½ cup fully cooked chili in a small saucepan until steaming. Shred 1 oz cheddar.","Toast 1 hamburger bun cut-side down in skillet for 30–60 seconds.","Place patty on bun, spoon on hot chili and top with cheddar. Serve immediately."]},{"id":"southBeefEnchiladas","name":"Beef Enchiladas","slot":"Dinner","cuisine":"Southern","emoji":"🫔","cal":670,"p":38,"c":61,"f":31,"ingredients":[["Ground beef",5,"oz"],["Corn tortillas",3,"each"],["Enchilada sauce",0.75,"cup"],["Cheddar cheese",1.5,"oz"]],"steps":["Preheat oven to 375°F. Brown 5 oz ground beef in skillet over medium heat for 6–8 minutes until it reaches 160°F.","Spread 2 tbsp of ¾ cup enchilada sauce across bottom of small baking dish. Warm 3 corn tortillas until pliable.","Divide cooked beef among tortillas, roll and place seam-side down in dish.","Pour over remaining enchilada sauce and scatter 1½ oz cheddar on top.","Bake uncovered 15–20 minutes until bubbling and cheese melts; rest 3 minutes."]},{"id":"southBeefBurritoBowl","name":"Beef and Bean Burrito Bowl","slot":"Dinner","cuisine":"Southern","emoji":"🥙","cal":650,"p":40,"c":78,"f":21,"ingredients":[["Ground beef",5,"oz"],["Cooked rice",1,"cup"],["Black beans",0.5,"cup"],["Salsa",0.25,"cup"],["Cheddar cheese",1,"oz"]],"steps":["Brown 5 oz ground beef in skillet over medium heat 6–8 minutes until 160°F; drain fat.","Drain and rinse ½ cup black beans and warm with 1 cup already-cooked rice until steaming.","Layer rice, beans and cooked beef in a serving bowl.","Top with ¼ cup salsa and 1 oz shredded cheddar."]},{"id":"southBeefyMac","name":"Beefy Mac and Cheese","slot":"Dinner","cuisine":"Southern","emoji":"🧀","cal":720,"p":40,"c":69,"f":32,"ingredients":[["Ground beef",5,"oz"],["Macaroni",3,"oz"],["Cheddar cheese",2,"oz"],["Milk",0.5,"cup"]],"steps":["Boil 3 oz dry macaroni according to package directions, typically 7–10 minutes; drain.","Brown 5 oz ground beef in skillet over medium heat for 6–8 minutes until center reaches 160°F; drain fat.","Warm ½ cup milk in small saucepan over low heat. Gradually stir in 2 oz shredded cheddar until melted.","Fold macaroni and cooked beef into the cheese sauce and heat together 1–2 minutes, stirring."]},{"id":"southStuffedPeppers","name":"Stuffed Bell Peppers","slot":"Dinner","cuisine":"Southern","emoji":"🫑","cal":560,"p":36,"c":55,"f":21,"ingredients":[["Bell pepper",1,"each"],["Ground beef",4,"oz"],["Cooked rice",0.75,"cup"],["Tomato sauce",0.5,"cup"],["Cheddar cheese",1,"oz"]],"steps":["Preheat oven to 375°F. Cut 1 bell pepper in half lengthwise and remove seeds.","Brown 4 oz ground beef in skillet over medium heat for 6–8 minutes until 160°F.","Combine beef with ¾ cup cooked rice and ½ cup tomato sauce. Fill pepper halves, packing filling gently.","Place stuffed halves in covered baking dish with ¼ cup water. Bake 25–35 minutes until pepper is tender.","Uncover, scatter 1 oz cheddar on top and bake another 5 minutes until melted."]},{"id":"southStuffedPepperCass","name":"Stuffed Pepper Casserole","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":590,"p":36,"c":60,"f":22,"ingredients":[["Ground beef",5,"oz"],["Bell pepper",1,"each"],["Cooked rice",1,"cup"],["Tomato sauce",0.75,"cup"],["Cheddar cheese",1,"oz"]],"steps":["Preheat oven to 375°F. Dice 1 bell pepper into small pieces.","Cook 5 oz ground beef and diced pepper together in skillet over medium heat 6–9 minutes until beef reaches 160°F.","Stir in 1 cup cooked rice and ¾ cup tomato sauce. Transfer mixture to small baking dish.","Top with 1 oz shredded cheddar and bake uncovered 15–20 minutes until bubbling."]},{"id":"southSausagePeppers","name":"Smoked Sausage and Peppers","slot":"Dinner","cuisine":"Southern","emoji":"🌭","cal":610,"p":28,"c":48,"f":34,"ingredients":[["Smoked sausage",6,"oz"],["Bell peppers",1,"each"],["Onion",0.5,"each"],["Cooked rice",0.75,"cup"]],"steps":["Slice 6 oz smoked sausage into rounds, slice 1 bell pepper and ½ onion into strips.","Brown sausage in nonstick skillet over medium heat for 4–5 minutes, stirring.","Add pepper and onion with 2 tbsp water; cover for 4 minutes then uncover and cook 2–3 minutes until tender.","Warm ¾ cup cooked rice until steaming. Spoon sausage and vegetables over rice."]},{"id":"southSausageGravyBake","name":"Sausage and Gravy Biscuit Bake","slot":"Dinner","cuisine":"Southern","emoji":"🥘","cal":720,"p":30,"c":58,"f":41,"ingredients":[["Breakfast sausage",5,"oz"],["Milk",0.75,"cup"],["All-purpose flour",2,"tbsp"],["Biscuit dough",4,"oz"]],"steps":["Preheat oven to 400°F. Brown 5 oz breakfast sausage in skillet over medium heat 6–8 minutes, breaking into crumbs until fully cooked.","Sprinkle 2 tbsp flour over sausage and stir for 1 minute.","Slowly whisk in ¾ cup milk; simmer over medium-low heat 3–5 minutes until gravy thickens.","Transfer sausage gravy to small baking dish and arrange 4 oz biscuit dough pieces over top, leaving gaps.","Bake 18–25 minutes until biscuits are golden and dough centers are fully cooked."]},{"id":"southCajunSausagePasta","name":"Cajun Sausage Pasta","slot":"Dinner","cuisine":"Southern","emoji":"🍝","cal":690,"p":31,"c":65,"f":34,"ingredients":[["Smoked sausage",5,"oz"],["Pasta",3,"oz"],["Heavy cream",0.25,"cup"],["Bell pepper",0.5,"each"],["Cajun seasoning",1,"tsp"]],"steps":["Cook 3 oz dry pasta according to package directions; drain.","Slice 5 oz smoked sausage and ½ bell pepper. Brown both in a nonstick skillet over medium heat for 5–7 minutes.","Lower heat and add ¼ cup heavy cream and 1 tsp Cajun seasoning. Simmer gently 2–3 minutes.","Toss pasta into sauce for 1 minute until hot and coated."]},{"id":"southCajunShrimpRice","name":"Cajun Shrimp and Rice","slot":"Dinner","cuisine":"Southern","emoji":"🍤","cal":560,"p":36,"c":67,"f":15,"ingredients":[["Shrimp",6,"oz"],["Cooked rice",1,"cup"],["Bell pepper",0.5,"each"],["Onion",0.25,"each"],["Cajun seasoning",1,"tsp"]],"steps":["Slice ½ bell pepper and dice ¼ onion. Pat 6 oz peeled, deveined shrimp dry.","Cook pepper and onion in nonstick skillet over medium heat with 2 tbsp water for 4–5 minutes.","Sprinkle 1 tsp Cajun seasoning over shrimp and add to skillet. Cook about 2–3 minutes per side until opaque and 145°F.","Warm 1 cup cooked rice until steaming and spoon the shrimp and vegetables over it."]},{"id":"southGarlicShrimp","name":"Garlic Butter Shrimp","slot":"Dinner","cuisine":"Southern","emoji":"🍤","cal":520,"p":35,"c":45,"f":22,"ingredients":[["Shrimp",6,"oz"],["Butter",1,"tbsp"],["Garlic",3,"clove"],["Cooked rice",0.75,"cup"],["Green beans",1,"cup"]],"steps":["Mince 3 garlic cloves. Pat 6 oz peeled, deveined shrimp dry.","Melt 1 tbsp butter in skillet over medium heat and stir in minced garlic for 30–45 seconds.","Add shrimp and cook 2–3 minutes on each side until pink, opaque and 145°F.","Warm ¾ cup cooked rice until steaming and steam 1 cup green beans with 2 tbsp water for 4–6 minutes.","Serve shrimp and garlic butter over rice with beans."]},{"id":"lunchHamCheese","name":"Ham and Cheese Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":450,"p":29,"c":38,"f":21,"ingredients":[["Ham",4,"oz"],["Cheddar cheese",1,"oz"],["Sandwich bread",2,"slice"],["Mustard",1,"tsp"]],"steps":["Lay out 2 slices sandwich bread and spread 1 tsp mustard evenly across one slice.","Layer 4 oz fully cooked ham and 1 oz cheddar onto the bread.","Top with remaining bread and cut in half. Serve cold, or toast in dry skillet 2–3 minutes per side until cheese melts."]},{"id":"lunchTurkeyCheese","name":"Turkey and Cheese Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":430,"p":32,"c":37,"f":18,"ingredients":[["Turkey slices",4,"oz"],["Cheddar cheese",1,"oz"],["Sandwich bread",2,"slice"],["Lettuce",1,"cup"]],"steps":["Wash and thoroughly dry 1 cup lettuce.","Lay out 2 slices sandwich bread. Layer 4 oz turkey slices, 1 oz cheddar and 1 cup lettuce onto one slice.","Place second slice on top, press lightly and cut in half. Keep chilled if not eating immediately."]},{"id":"lunchClub","name":"Southern Club Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":590,"p":38,"c":46,"f":29,"ingredients":[["Turkey slices",3,"oz"],["Ham",2,"oz"],["Bacon",2,"slice"],["Sandwich bread",3,"slice"],["Tomato",0.5,"each"]],"steps":["Cook 2 slices bacon in skillet over medium heat 6–8 minutes until crisp; drain.","Toast 3 slices sandwich bread until golden and slice ½ tomato.","On first slice of bread layer 3 oz turkey and tomato, then add second slice of toast.","Layer 2 oz ham and crisp bacon over middle toast; cover with final bread slice.","Cut diagonally into halves; secure with toothpicks before slicing if desired."]},{"id":"lunchBuffaloWrap","name":"Buffalo Chicken Wrap","slot":"Lunch","cuisine":"Southern","emoji":"🌯","cal":550,"p":39,"c":46,"f":23,"ingredients":[["Chicken breast",4,"oz"],["Flour tortilla",1,"each"],["Buffalo sauce",2,"tbsp"],["Lettuce",1,"cup"],["Ranch dressing",1,"tbsp"]],"steps":["Cut 4 oz chicken breast into strips. Cook in a nonstick skillet over medium heat for 6–9 minutes, turning until 165°F.","Toss the hot cooked chicken with 2 tbsp Buffalo sauce in a clean bowl.","Wash and dry 1 cup lettuce. Warm 1 flour tortilla in a dry skillet for 15–20 seconds until flexible.","Spread 1 tbsp ranch dressing on the tortilla, add lettuce and Buffalo chicken, fold in the sides and roll firmly."]},{"id":"lunchTurkeyRanch","name":"Turkey Bacon Ranch Wrap","slot":"Lunch","cuisine":"Southern","emoji":"🌯","cal":560,"p":35,"c":44,"f":25,"ingredients":[["Turkey slices",4,"oz"],["Bacon",2,"slice"],["Flour tortilla",1,"each"],["Lettuce",1,"cup"],["Ranch dressing",1,"tbsp"]],"steps":["Cook 2 slices bacon in a skillet over medium heat for 6–8 minutes until crisp; drain on paper towels.","Wash and dry 1 cup lettuce; lay out 4 oz ready-to-eat turkey slices.","Warm 1 flour tortilla briefly, then spread with 1 tbsp ranch dressing.","Layer turkey, crisp bacon and lettuce along the center of the tortilla. Fold the sides inward and roll tightly."]},{"id":"lunchHamWrap","name":"Ham and Cheese Wrap","slot":"Lunch","cuisine":"Southern","emoji":"🌯","cal":500,"p":30,"c":42,"f":23,"ingredients":[["Ham",4,"oz"],["Cheddar cheese",1,"oz"],["Flour tortilla",1,"each"],["Lettuce",1,"cup"]],"steps":["Wash and dry 1 cup lettuce and cut 4 oz fully cooked ham into strips, if needed.","Warm 1 flour tortilla in a dry skillet for 15 seconds so it bends without tearing.","Place the ham, 1 oz shredded cheddar and the 1 cup lettuce in a strip down the middle.","Fold two opposite sides inward, roll the wrap tightly and cut in half."]},{"id":"lunchCheeseburger","name":"Homestyle Cheeseburger","slot":"Lunch","cuisine":"Southern","emoji":"🍔","cal":650,"p":39,"c":42,"f":37,"ingredients":[["Ground beef",5,"oz"],["Hamburger bun",1,"each"],["Cheddar cheese",1,"oz"],["Lettuce",1,"cup"],["Tomato",0.5,"each"]],"steps":["Shape 5 oz ground beef into a burger patty about ¾ inch thick and indent the middle slightly.","Cook in a nonstick skillet over medium heat for 4–6 minutes per side until the center reaches 160°F.","Place 1 oz cheddar on the burger during the final minute so it melts.","Slice ½ tomato, rinse 1 cup lettuce and toast 1 hamburger bun for 30–60 seconds. Assemble burger with lettuce and tomato."]},{"id":"lunchChiliBurger","name":"Chili Cheeseburger Lunch","slot":"Lunch","cuisine":"Southern","emoji":"🍔","cal":720,"p":41,"c":53,"f":39,"ingredients":[["Ground beef",5,"oz"],["Hamburger bun",1,"each"],["Chili",0.5,"cup"],["Cheddar cheese",1,"oz"]],"steps":["Shape 5 oz ground beef into a patty; cook in a skillet over medium heat for 4–6 minutes per side until 160°F.","In a small saucepan heat ½ cup prepared chili over medium-low heat, stirring, until steaming throughout.","Put 1 oz shredded cheddar on the hot patty, cover for 30–60 seconds to soften.","Toast 1 hamburger bun briefly, place the cooked burger inside, spoon the hot chili over it and serve."]},{"id":"lunchSloppyJoe","name":"Sloppy Joe Sandwich","slot":"Lunch","cuisine":"Southern","emoji":"🥪","cal":540,"p":32,"c":54,"f":22,"ingredients":[["Ground beef",4,"oz"],["Hamburger bun",1,"each"],["Tomato sauce",0.4,"cup"],["Onion",0.25,"each"]],"steps":["Finely dice ¼ onion. Brown the onion with 4 oz ground beef in a nonstick skillet over medium heat for 6–8 minutes, stirring until beef reaches 160°F.","Drain excess fat, then stir in ⅖ cup tomato sauce (about 6 tbsp plus 1 tsp).","Simmer uncovered on low heat for 8–10 minutes until the tomato sauce thickly coats the meat.","Toast 1 hamburger bun for 30–60 seconds and spoon the hot beef mixture onto it."]},{"id":"lunchChickenDumpling","name":"Chicken and Dumplings Bowl","slot":"Lunch","cuisine":"Southern","emoji":"🥣","cal":500,"p":33,"c":52,"f":18,"ingredients":[["Chicken breast",4,"oz"],["Chicken broth",1.5,"cup"],["Biscuit dough",3,"oz"],["Carrots",0.5,"cup"],["Celery",0.5,"cup"]],"steps":["Cut 4 oz chicken breast into small pieces. Dice ½ cup carrots and ½ cup celery.","Bring 1½ cups chicken broth to a gentle simmer. Add the chicken and chopped vegetables.","Cover and simmer 10–13 minutes, stirring occasionally until the chicken reaches 165°F and vegetables soften.","Cut 3 oz biscuit dough into bite-size pieces and place on the surface of the simmering broth.","Cover and simmer gently for 10–12 minutes without vigorous stirring, until the centers of the dumplings are fully cooked and not doughy. Serve hot."]},{"id":"lunchVegBeefSoup","name":"Vegetable Beef Soup","slot":"Lunch","cuisine":"Southern","emoji":"🥣","cal":430,"p":31,"c":45,"f":14,"ingredients":[["Beef stew meat",4,"oz"],["Mixed vegetables",1.5,"cup"],["Beef broth",2,"cup"],["Potatoes",0.75,"cup"]],"steps":["Cut 4 oz beef stew meat and ¾ cup potatoes into ½-inch cubes; measure 1½ cups mixed vegetables.","Put beef and 2 cups beef broth in a covered saucepan. Bring to a boil, reduce to a gentle simmer and cook 45–70 minutes until beef is beginning to soften.","Add potatoes and mixed vegetables. Simmer covered for another 15–25 minutes until potatoes are tender and beef is fork-tender.","Check soup is steaming hot throughout. Ladle the beef, vegetables and broth into a bowl."]},{"id":"lunchChili","name":"Homemade Chili","slot":"Lunch","cuisine":"Southern","emoji":"🍲","cal":520,"p":34,"c":55,"f":20,"ingredients":[["Ground beef",4,"oz"],["Kidney beans",0.75,"cup"],["Diced tomatoes",1,"cup"],["Chili seasoning",1,"tbsp"]],"steps":["Cook 4 oz ground beef in a saucepan over medium heat for 6–8 minutes, breaking into crumbles until it reaches 160°F; drain if needed.","Drain and rinse ¾ cup cooked or canned kidney beans.","Add the beans, 1 cup diced tomatoes and 1 tbsp chili seasoning to the beef.","Simmer gently without a lid for 15–20 minutes, stirring occasionally until thick. Add a splash of water if it becomes too thick."]},{"id":"lunchTenderBasket","name":"Chicken Tender Basket","slot":"Lunch","cuisine":"Southern","emoji":"🍗","cal":630,"p":37,"c":58,"f":28,"ingredients":[["Chicken tenders",5,"oz"],["French fries",1,"cup"],["All-purpose flour",0.4,"cup"],["Ranch dressing",1,"tbsp"]],"steps":["Preheat the oven to 425°F for 1 cup frozen French fries, or follow the fries' package directions.","Pat 5 oz chicken tenders dry and press them into ⅖ cup all-purpose flour, discarding flour that touches raw chicken.","Cook the coated tenders in a lightly oiled nonstick skillet over medium heat for 4–6 minutes per side until golden and the center reaches 165°F. Added oil is not included in the listed ingredients.","Bake 1 cup fries according to the package, usually 18–25 minutes, turning halfway until golden and hot.","Serve cooked chicken tenders with hot fries and 1 tbsp ranch dressing for dipping."]}]);
